            lithotherapie = "Pietra di pacificazione, l'amazzonite è ritenuta in grado di calmare lo stress e facilitare una comunicazione sincera con gli altri."
        ),
        "chrysoprase" to GemTranslation(
            nom = "Crisoprasio",
            descriptionCourte = "Il verde mela più vivo della famiglia delle calcedonie.",
            descriptionLongue = "Il crisoprasio è la varietà di calcedonio dal verde mela più intenso, colorato da tracce di nichel. Apprezzato sin dall'Antichità, ha conosciuto una rinnovata popolarità nel XVIII secolo, in particolare nell'arredamento di Federico il Grande di Prussia.",
            particularites = "Il colore può attenuarsi in caso di disidratazione prolungata o forte calore; si conserva meglio leggermente umido.",
            lithotherapie = "Il crisoprasio è tradizionalmente associato alla speranza e all'ottimismo, aprendo il cuore a nuove prospettive."
        ),
        "beryl-vert" to GemTranslation(
            nom = "Berillo verde",
            descriptionCourte = "Il verde «ordinario» del berillo, privo del cromo che ne farebbe uno smeraldo.",
            descriptionLongue = "Colorato dal ferro piuttosto che dal cromo o dal vanadio, il berillo verde non ha diritto alla denominazione «smeraldo» in gemmologia rigorosa, ma offre pietre pulite e luminose a un prezzo molto più accessibile.",
            particularites = "Si distingue dallo smeraldo tramite lo spettroscopio: assenza delle righe di assorbimento del cromo/vanadio.",
            lithotherapie = "Il berillo verde è ritenuto in grado di apportare equilibrio emotivo e rinnovamento, aiutando a voltare pagina dopo un periodo difficile."
        ),
        "sillimanite" to GemTranslation(
            nom = "Sillimanite",
            descriptionCourte = "Una cugina poco conosciuta dell'andalusite e del cianite, talvolta a occhio di gatto.",
            descriptionLongue = "Polimorfo dell'andalusite e del cianite (stessa formula, struttura cristallina diversa), la sillimanite si presenta dal verde-blu al bruno, talvolta con un effetto cangiante ricercato a cabochon.",
            particularites = "Può presentare un effetto occhio di gatto molto netto quando è tagliata a cabochon perpendicolarmente alle fibre.",
            lithotherapie = "La sillimanite è associata alla chiarezza mentale, un sostegno per mettere ordine nei propri pensieri e priorità."
        ),
        "seraphinite" to GemTranslation(
            nom = "Serafinite",
            descriptionCourte = "Un verde profondo attraversato da piume argentate setose.",
            descriptionLongue = "La serafinite, nome commerciale di una varietà di clinocloro, presenta motivi piumati argentati su fondo verde scuro, che evocano ali d'angelo — da cui il suo nome. Sempre lavorata a cabochon lucidato per rivelare questa chatoyance setosa.",
            particularites = "Estremamente tenera: da riservare a gioielli poco esposti agli urti (pendenti, orecchini).",
            lithotherapie = "Pietra di guarigione profonda, la serafinite è ritenuta in grado di aiutare a liberarsi dagli schemi ripetitivi e ad avviare un rinnovamento interiore."
        ),
        "grenat-grossulaire" to GemTranslation(
            nom = "Granato grossularia",
            descriptionCourte = "Il granato dal verde al giallo-verde, cugino poco colorato della tsavorite e dell'essonite.",
            descriptionLongue = "La grossularia copre un'ampia gamma dall'incolore al verde intenso, passando per il giallo-verde («granato del Mali»), a seconda delle tracce di ferro, manganese o vanadio presenti — la tsavorite e l'essonite ne sono le varietà più celebri.",
            particularites = "Famiglia di granati più diversificata nei colori, dall'incolore al verde profondo della tsavorite.",
            lithotherapie = "Il granato grossularia è associato all'abbondanza e alla vitalità, un sostegno nei periodi di ricostruzione personale."
        ),
        "diopside" to GemTranslation(
            nom = "Diopside cromifero",
            descriptionCourte = "Un verde abete profondo dovuto al cromo, cugino del granato demantoide.",
            descriptionLongue = "Il diopside cromifero deve il suo verde intenso, vicino a quello dello smeraldo, a tracce di cromo. Presente negli stessi giacimenti dei diamanti (kimberliti), ne è talvolta un minerale indicatore per i prospettori.",
            particularites = "Bassa durezza da tenere in considerazione in gioielleria; alcune pietre presentano asterismo o effetto occhio di gatto.",
            lithotherapie = "Il diopside cromifero è ritenuto in grado di favorire la connessione con la natura e l'equilibrio emotivo quotidiano."
        ),
        "jade-nephrite" to GemTranslation(
            nom = "Giada nefrite",
            descriptionCourte = "La giada storica della Cina e della Nuova Zelanda, distinta dalla giadeite.",
            descriptionLongue = "Prima della scoperta della giadeite birmana nel XVIII secolo, tutta la giada lavorata nella Cina imperiale, in Nuova Zelanda (il pounamu maori) e nell'America precolombiana era nefrite — un anfibolo intrecciato in fibre microscopiche che le conferisce una tenacità eccezionale.",
            particularites = "Struttura a fibre feltrate che la rende più resistente agli urti della giadeite, nonostante una durezza leggermente inferiore.",
            lithotherapie = "Pietra di saggezza e armonia sin dall'Antichità cinese, la giada nefrite è ritenuta in grado di apportare serenità, protezione e longevità."
        ),
        "maw-sit-sit" to GemTranslation(
            nom = "Maw-sit-sit",
            descriptionCourte = "Un verde elettrico venato di nero, dal nome di un villaggio birmano.",
            descriptionLongue = "Il maw-sit-sit, chiamato così dal villaggio birmano dove fu scoperto nel 1963, è una roccia a dominante di giadeite e kosmocloro (pirosseno cromifero) che offre un verde vivo attraversato da venature nere, molto apprezzata in Asia.",
            particularites = "Giacimento unico al mondo fino ad oggi, situato in prossimità delle miniere di giadeite di Hpakant.",
            lithotherapie = "Il maw-sit-sit è associato al rinnovamento e alla circolazione di un'energia positiva nei momenti di transizione."
        ),
        "tourmaline-chrome" to GemTranslation(
            nom = "Tormalina cromifera",
            descriptionCourte = "Un verde profondo e saturo dovuto al cromo e al vanadio, distinto dal verde «classico».",
            descriptionLongue = "Colorata dal cromo e dal vanadio piuttosto che dal ferro, la tormalina cromifera presenta un verde più saturo e profondo rispetto alla tormalina verde ordinaria, con un dicroismo marcato tra il verde e il bruno-verde a seconda dell'angolo di osservazione.",
            particularites = "Dicroismo marcato: l'orientamento della tavola è determinante per rivelare la tonalità più satura.",
            lithotherapie = "La tormalina cromifera è ritenuta in grado di stimolare la vitalità favorendo al contempo l'apertura del cuore e la compassione."
        ),
        "saphir-vert" to GemTranslation(
            nom = "Zaffiro verde",
            descriptionCourte = "Un verde discreto spesso dicroico, il colore più accessibile del corindone.",
            descriptionLongue = "Colorato dal ferro, lo zaffiro verde presenta spesso un netto dicroismo (verde e giallo-verde a seconda dell'angolo), una firma che permette di distinguerlo da altre gemme verdi. È generalmente il colore più accessibile tra gli zaffiri.",
            particularites = "Dicroismo marcato tra verde e giallo-verde a seconda dell'asse di osservazione, utile per l'identificazione.",
            lithotherapie = "Lo zaffiro verde è associato all'equilibrio interiore e alla saggezza, un sostegno per prendere le distanze e vedere con lucidità."
        ),
        "emeraude" to GemTranslation(
            nom = "Smeraldo",
            descriptionCourte = "Il verde più ricercato della gioielleria.",
            descriptionLongue = "Lo smeraldo deve il suo verde profondo al cromo e/o al vanadio. Le sue inclusioni naturali, soprannominate «giardino», testimoniano la sua autenticità e sono generalmente stabilizzate mediante un trattamento all'olio di cedro, una pratica accettata e attesa sul mercato.",
            particularites = "Trattamento all'olio quasi sistematico; pietra fragile che richiede precauzioni.",
            lithotherapie = "Pietra d'amore e di saggezza, lo smeraldo è tradizionalmente ritenuto capace di placare le tensioni emotive e favorire la fedeltà e l'armonia nelle relazioni."
        ),
        "peridot" to GemTranslation(
            nom = "Peridoto",
            descriptionCourte = "Verde oliva luminoso, mai trattato.",
            descriptionLongue = "Il peridoto è una delle rare gemme composte da un'unica specie minerale (l'olivina) e non viene mai trattato. La sua forte birifrangenza rende talvolta visibile a occhio nudo lo sdoppiamento degli spigoli attraverso la tavola della pietra.",
            particularites = "Birifrangenza visibile a occhio nudo; alcune pietre provengono da meteoriti (pallasiti).",
            lithotherapie = "Il peridoto è associato al benessere generale e al lasciar andare, aiutando a liberarsi da rancori e risentimenti."
        ),
        "tsavorite" to GemTranslation(
            nom = "Tsavorite",
            descriptionCourte = "Alternativa sostenibile e non trattata allo smeraldo.",
            descriptionLongue = "Scoperta nel 1967 nei pressi del parco nazionale di Tsavo, in Kenya, la tsavorite deve il suo colore verde al vanadio e al cromo. Sempre non trattata, offre una brillantezza e una purezza spesso superiori a quelle dello smeraldo.",
            particularites = "Mai trattata; giacimenti limitati che rendono le pietre di grandi dimensioni molto rare.",
            lithotherapie = "La tsavorite è ritenuta stimolare la vitalità e la fiducia in sé stessi, un sostegno per affrontare le sfide con energia."
        ),
        "jade-jadeite" to GemTranslation(
            nom = "Giada (giadeite)",
            descriptionCourte = "La pietra sacra della cultura cinese.",
            descriptionLongue = "La giadeite forma un aggregato microcristallino di eccezionale tenacità, il che la distingue dalla nefrite, l'altro minerale chiamato «giada». Venerata in Cina come «pietra del cielo», simboleggia la purezza e la virtù.",
            particularites = "Estremamente tenace nonostante una durezza moderata; qualità «imperiale» di un verde traslucido molto raro.",
            lithotherapie = "La giada giadeite è ritenuta portare fortuna e protezione, favorendo al contempo l'armonia nelle relazioni e la serenità interiore."
        ),
        "tourmaline-verte" to GemTranslation(
            nom = "Tormalina verde (Verdelite)",
            descriptionCourte = "Verde colorato dal ferro o dal cromo.",
            descriptionLongue = "La verdelite copre un'ampia gamma di verdi, dal verde menta chiaro al verde foresta profondo, a seconda delle tracce di ferro, cromo o vanadio. Il suo forte pleocroismo può far variare sensibilmente la tonalità a seconda dell'angolo di taglio.",
            particularites = "Forte birifrangenza; i tagliatori orientano la pietra per ottimizzare il colore.",
            lithotherapie = "La tormalina verde è associata all'equilibrio emotivo e alla rigenerazione, un sostegno dopo un periodo di stanchezza morale."
        ),
        "demantoide" to GemTranslation(
            nom = "Granato demantoide",
            descriptionCourte = "Dispersione superiore a quella del diamante.",
            descriptionLongue = "Il demantoide è la varietà verde più apprezzata del granato andradite, colorata dal cromo. La sua dispersione (il «fuoco») supera quella del diamante, e le sue inclusioni fibrose a «coda di cavallo» (bissolite) sono una garanzia di autenticità ricercata dai collezionisti.",
            particularites = "Dispersione ottica eccezionale; inclusioni a «coda di cavallo» caratteristiche delle pietre degli Urali.",
            lithotherapie = "Il granato demantoide è ritenuto attirare la prosperità e ravvivare la gioia di vivere quotidiana."
        ),
        "uvarovite" to GemTranslation(
            nom = "Granato uvarovite",
            descriptionCourte = "Verde smeraldo in druse di micro-cristalli.",
            descriptionLongue = "L'uvarovite forma quasi sempre minuscoli cristalli in druse, raramente abbastanza grandi da essere tagliati a faccette. Il suo intenso verde smeraldo, dovuto al cromo, ne fa comunque un pezzo da collezione molto ricercato allo stato grezzo.",
            particularites = "Cristalli quasi sempre troppo piccoli per la taglia a faccette; collezionata grezza in drusa.",
            lithotherapie = "L'uvarovite è associata alla calma e a una migliore connessione con la natura circostante."
        ),
        "vesuvianite" to GemTranslation(
            nom = "Vesuvianite (idocrasio)",
            descriptionCourte = "Scoperta sulle pendici del Vesuvio.",
            descriptionLongue = "Descritta per la prima volta sulle colate del Vesuvio, la vesuvianite (o idocrasio) presenta tonalità dal verde oliva al verde bottiglia. La sua varietà massiva e compatta, la californite, viene talvolta utilizzata come sostituto della giada.",
            particularites = "La varietà massiva californite può imitare la giada nefrite.",
            lithotherapie = "La vesuvianite è ritenuta incoraggiare il superamento dei propri limiti e stimolare la creatività nei progetti personali."
        ),
        "prehnite" to GemTranslation(
            nom = "Prehnite",
            descriptionCourte = "Verde pistacchio traslucido.",
            descriptionLongue = "Primo minerale ad essere stato battezzato con il nome di una persona (il colonnello Von Prehn), la prehnite forma aggregati mammellonari dal verde pistacchio al verde giallo, tagliati a cabochon o talvolta a faccette quando il cristallo lo consente.",
            particularites = "Spesso tagliata a cabochon; talvolta confusa con il crisoprasio.",
            lithotherapie = "La prehnite è associata alla serenità e all'ascolto della propria intuizione, un sostegno per la meditazione."
        ),
        "chrysocolle" to GemTranslation(
            nom = "Crisocolla",
            descriptionCourte = "Blu-verde rameico, spesso in ganga di quarzo.",
            descriptionLongue = "Colorata dal rame, la crisocolla è raramente abbastanza dura da essere tagliata da sola: viene il più delle volte stabilizzata in ganga di quarzo («crisocolla in quarzo»), che le conferisce la durezza necessaria per la gioielleria pur conservando le sue tonalità dal turchese al verde profondo.",
            particularites = "Troppo tenera allo stato puro; impregnata di quarzo per la gioielleria.",
            lithotherapie = "La crisocolla è ritenuta facilitare l'espressione di sé e placare le tensioni emotive legate alla comunicazione."
        ),
        "variscite" to GemTranslation(
            nom = "Variscite",
            descriptionCourte = "Verde mela traslucido, cugina del turchese.",
            descriptionLongue = "Fosfato di alluminio chimicamente affine al turchese, la variscite presenta un verde mela-verde smeraldo venato, spesso attraversato da sottili venature bianche di crandallite. Tagliata a cabochon, resta poco diffusa sul mercato.",
            particularites = "Spesso confusa con il turchese; sempre tagliata a cabochon.",
            lithotherapie = "La variscite è associata all'equilibrio emotivo, apportando un senso di conforto e sicurezza interiore."
        ),
        "serpentine" to GemTranslation(
            nom = "Serpentino (bowenite)",
            descriptionCourte = "Alternativa accessibile alla giada.",
            descriptionLongue = "La bowenite, varietà compatta e dura di serpentino, è impiegata come sostituto della giada nefrite fin dall'antichità in Nuova Zelanda (pounamu) e in Cina. Il suo verde traslucido e la sua tenacità ne fanno una pietra ornamentale apprezzata.",
            particularites = "La varietà bowenite, più dura e traslucida, è la più ricercata in gioielleria.",
            lithotherapie = "Il serpentino è ritenuto favorire la rigenerazione e il radicamento, un sostegno nei periodi di ricostruzione personale."
        ),
        "grandidierite" to GemTranslation(
            nom = "Grandidierite",
            descriptionCourte = "Una delle gemme più rare al mondo, blu-verde pleocroica.",
            descriptionLongue = "Scoperta in Madagascar nel 1902 e battezzata in onore dell'esploratore Alfred Grandidier, la grandidierite conta solo una manciata di cristalli trasparenti tagliabili conosciuti al mondo. Il suo forte pleocroismo fa passare il colore dal blu-verde al bianco a seconda dell'angolo di osservazione.",
            particularites = "Meno di una ventina di pietre tagliate trasparenti censite nel mondo.",
            lithotherapie = "Minerale raro e prezioso, la grandidierite è associata in litoterapia a una serenità profonda e all'apertura del cuore."
        ),
        "azurite" to GemTranslation(
            nom = "Azzurrite",
            descriptionCourte = "Il blu profondo del rame, spesso intercresciuto con la malachite.",
            descriptionLongue = "L'azzurrite forma cristalli e masse di un blu profondo e intenso, colorata dal rame. Instabile nel lungo periodo (può trasformarsi in malachite a contatto con l'umidità), viene lavorata soprattutto a cabochon o come oggetto decorativo, spesso associata alla malachite verde.",
            particularites = "Può alterarsi progressivamente in malachite (pseudomorfosi); da proteggere dall'umidità e dalla luce diretta.",
            lithotherapie = "L'azzurrite è ritenuta stimolare l'intuizione e la chiarezza mentale, un sostegno per la riflessione e il processo decisionale."
        ),
        "sodalite" to GemTranslation(
            nom = "Sodalite",
            descriptionCourte = "Un blu profondo venato di bianco, spesso confuso con il lapislazzuli.",
            descriptionLongue = "La sodalite presenta un blu reale venato di calcite bianca, simile al lapislazzuli ma priva delle inclusioni dorate di pirite. Utilizzata a cabochon, per intarsi e oggetti decorativi fin dalla sua scoperta in Groenlandia nel XIX secolo.",
            particularites = "Si distingue dal lapislazzuli per l'assenza di pagliuzze dorate di pirite e per una densità inferiore.",
            lithotherapie = "La sodalite è associata alla comunicazione chiara e alla logica, placando al contempo l'ansia mentale."
        ),
        "larimar" to GemTranslation(
            nom = "Larimar",
            descriptionCourte = "L'unico blu caraibico di una pectolite trovata su una sola isola.",
            descriptionLongue = "Il larimar è una varietà di pectolite dal blu turchese al blu cielo che evoca le acque dei Caraibi; il suo colore proviene da tracce di rame. Un giacimento quasi unico al mondo nella Repubblica Dominicana ne fa una gemma geograficamente esclusiva.",
            particularites = "Giacimento quasi esclusivo; il nome combina «Larissa» (figlia dello scopritore) e «mar» (mare in spagnolo).",
            lithotherapie = "Pietra di serenità, il larimar è ritenuto placare lo stress e facilitare una comunicazione sincera proveniente dal cuore."
        ),
        "lazulite" to GemTranslation(
            nom = "Lazulite",
            descriptionCourte = "Un blu profondo da non confondere con il lapislazzuli, nonostante la somiglianza del nome.",
            descriptionLongue = "La lazulite forma cristalli di un blu azzurro intenso fino all'indaco, foneticamente simile al lapislazzuli ma chimicamente e mineralogicamente senza alcuna relazione. Rara in qualità da taglio, è soprattutto collezionata come esemplare.",
            particularites = "Da non confondere con la lazurite (componente del lapislazzuli) nonostante la vicinanza dei nomi.",
            lithotherapie = "La lazulite è associata all'introspezione e alla calma mentale, un sostegno per la meditazione e la riflessione interiore."
        ),
        "hauyne" to GemTranslation(
            nom = "Haüyna",
            descriptionCourte = "Un blu oltremare intenso nelle rocce vulcaniche, raro cugino del lapislazzuli.",
            descriptionLongue = "L'haüyna, battezzata in onore del cristallografo René Just Haüy, presenta un blu oltremare profondo simile alla lazurite del lapislazzuli, ma si trova in cristalli isolati nelle lave vulcaniche, eccezionalmente tagliabile a faccette.",
            particularites = "Cristalli gemma raramente più grandi di pochi millimetri; taglio a faccette eccezionale.",
            lithotherapie = "L'haüyna, minerale raro, è associata in litoterapia all'espressione autentica di sé e alla fiducia nella propria voce."
        ),
        "cavansite" to GemTranslation(
            nom = "Cavansite",
            descriptionCourte = "Un blu turchese elettrico in rosette cristalline, star delle mostre mineralogiche.",
            descriptionLongue = "La cavansite forma rosette di cristalli blu turchese vivo che tappezzano geodi di basalto, apprezzata soprattutto dai collezionisti di minerali per la sua brillantezza vitrea e il colore saturo, raramente tagliata a causa delle piccole dimensioni cristalline.",
            particularites = "Giacimento quasi esclusivo nei basalti del Deccan indiano; praticamente mai tagliata a faccette.",
            lithotherapie = "La cavansite è ritenuta favorire il risveglio spirituale e la chiarezza mentale nei momenti di interrogativo interiore."
        ),
        "celestite" to GemTranslation(
            nom = "Celestina",
            descriptionCourte = "Un blu pallido celeste, minerale tenero soprattutto collezionato in geode.",
            descriptionLongue = "La celestina forma cristalli tabulari di un delicato blu pallido che evoca il cielo, da cui il nome. La sua estrema tenerezza la riserva quasi esclusivamente alla collezione mineralogica e alla geode decorativa piuttosto che alla gioielleria.",
            particularites = "Troppo tenera e sfaldabile per un uso in gioielleria; essenzialmente una pietra da collezione e decorazione.",
            lithotherapie = "Pietra di profonda calma, la celestina è ritenuta favorire un sonno sereno e placare i pensieri agitati."
        ),
        "euclase" to GemTranslation(
            nom = "Euclasio",
            descriptionCourte = "Un blu-verde cristallino di notevole trasparenza, estremamente fragile.",
            descriptionLongue = "L'euclasio («ben sfaldato» in greco) deve il suo nome alla sua sfaldatura perfetta, che lo rende estremamente delicato da tagliare. I suoi cristalli blu-verdi di grande purezza sono ricercati dai collezionisti di pietre tagliate rare.",
            particularites = "Sfaldatura perfetta in una direzione: tra le gemme più delicate da tagliare e da indossare.",
            lithotherapie = "L'euclasio è associato alla chiarezza di espressione e alla serenità, un sostegno per comunicare con precisione."
        ),
        "topaze-bleue" to GemTranslation(
            nom = "Topazio blu",
            descriptionCourte = "Il blu profondo ottenuto tramite irradiazione e riscaldamento di un topazio incolore.",
            descriptionLongue = "Il topazio blu naturale è estremamente raro; quasi tutte le pietre in commercio («Sky», «Swiss», «London Blue») provengono da topazio incolore irradiato e poi riscaldato per sviluppare sfumature di blu stabili e durature.",
            particularites = "Colore ottenuto quasi sistematicamente tramite irradiazione seguita da trattamento termico, stabile e permanente.",
            lithotherapie = "Il topazio blu è ritenuto favorire una comunicazione serena e aiutare a esprimere con calma le proprie emozioni."
        ),
        "tourmaline-bleue" to GemTranslation(
            nom = "Tormalina blu (indicolite)",
            descriptionCourte = "Un blu profondo distinto dal blu-verde rameico della Paraíba.",
            descriptionLongue = "L'indicolite è la varietà dal blu al blu-verde della tormalina elbaite, colorata dal ferro, priva del rame caratteristico della Paraíba. Le sue tonalità più scure e smorzate ne fanno una gemma distinta, talvolta confusa con l'acquamarina.",
            particularites = "Si distingue dalla tormalina Paraíba per l'assenza di rame e per un tono generalmente più scuro.",
            lithotherapie = "La tormalina blu (indicolite) è associata all'espressione di sé e alla distensione delle tensioni legate alla comunicazione."
        ),
        "zircon-bleu" to GemTranslation(
            nom = "Zircone blu",
            descriptionCourte = "Lo zircone più richiesto sul mercato, blu vivo ottenuto tramite riscaldamento.",
            descriptionLongue = "Lo zircone blu, colore più commercializzato della specie, è ottenuto quasi sistematicamente tramite trattamento termico dello zircone marrone cambogiano. La sua brillantezza adamantina e la sua forte dispersione ne fanno un'alternativa apprezzata e accessibile allo zaffiro blu.",
            particularites = "Trattamento termico quasi sistematico e stabile; forte dispersione vicina a quella del diamante.",
            lithotherapie = "Lo zircone blu è ritenuto apportare calma mentale e chiarezza, un sostegno per i periodi di riflessione importanti."
        ),
        "hemimorphite" to GemTranslation(
            nom = "Emimorfite",
            descriptionCourte = "Mammelloni blu-verdi che evocano il turchese o la crisocolla.",
            descriptionLongue = "L'emimorfite forma aggregati botrioidali blu-verdi spesso confusi con il turchese o la crisocolla. Il suo nome («mezza forma») deriva dai suoi cristalli con simmetria diversa a ciascuna estremità, una curiosità cristallografica.",
            particularites = "Spesso confusa visivamente con la crisocolla o il turchese; l'identificazione richiede un test di durezza.",
            lithotherapie = "L'emimorfite è associata alla comunicazione autentica e alla guarigione delle ferite emotive legate all'espressione di sé."
        ),
        "shattuckite" to GemTranslation(
            nom = "Shattuckite",
            descriptionCourte = "Un blu profondo e setoso, raro cugino della crisocolla.",
            descriptionLongue = "La shattuckite offre un blu intenso e setoso in aggregati fibrosi, spesso associata alla crisocolla e alla malachite nei giacimenti di rame namibiani. Sempre lavorata a cabochon per rivelare la sua discreta cangianza.",
            particularites = "Troppo tenera per la taglia a faccette; sempre lavorata a cabochon.",
            lithotherapie = "La shattuckite è ritenuta rafforzare l'intuizione e facilitare una comunicazione più consapevole con sé stessi."
        ),
        "sapphirine" to GemTranslation(
            nom = "Saffirina",
            descriptionCourte = "Una gemma blu-grigia ultra-rara, senza alcuna parentela con il corindone.",
            descriptionLongue = "Nonostante il nome evocativo, la saffirina non è imparentata con il corindone: è un silicato distinto dal blu-grigio al violaceo, formatosi in rocce metamorfiche ad altissima temperatura, tra le gemme tagliate più rare al mondo.",
            particularites = "Una delle gemme tagliate più rare al mondo: alcune decine di pietre a faccette conosciute.",
            lithotherapie = "Minerale raro, la saffirina è associata in litoterapia a una calma profonda e alla protezione emotiva."
        ),
        "dumortierite" to GemTranslation(
            nom = "Dumortierite",
            descriptionCourte = "Un blu-violetto intenso in fibre sottili, spesso incluso nel quarzo.",
            descriptionLongue = "La dumortierite forma aggregati fibrosi blu-violetti profondi, raramente in cristalli abbastanza grandi da essere tagliati da soli: la si trova più spesso in dense inclusioni che colorano un quarzo massivo utilizzato a cabochon o in perline.",
            particularites = "Spesso rinvenuta sotto forma di quarzo massivo fortemente incluso di dumortierite piuttosto che in cristallo puro.",
            lithotherapie = "La dumortierite è ritenuta sviluppare la pazienza e la disciplina mentale, un sostegno per gli apprendimenti impegnativi."
        ),
        "afghanite" to GemTranslation(
            nom = "Afghanite",
            descriptionCourte = "Un blu simile al lapislazzuli descritto di recente, originario degli stessi giacimenti del lapislazzuli.",
            descriptionLongue = "Descritta scientificamente nel 1968, l'afghanite si trova negli stessi giacimenti di marmo del lapislazzuli afghano, condividendo una tonalità blu simile. Estremamente rara in pietra a faccette, resta soprattutto una curiosità da collezione.",
            particularites = "Scoperta mineralogica tardiva (1968); le pietre tagliate a faccette sono tra le più rare del mercato.",
            lithotherapie = "L'afghanite è associata a una profonda calma interiore e a una forma di dolce protezione emotiva."
        ),
        "saphir-bleu" to GemTranslation(
            nom = "Zaffiro blu",
            descriptionCourte = "Il blu di riferimento nell'alta gioielleria.",
            descriptionLongue = "Lo zaffiro blu deve il suo colore al ferro e al titanio. Il «blu vellutato» delle pietre non trattate del Kashmir resta il punto di riferimento assoluto per gli intenditori, seguito dalle provenienze della Birmania e dello Sri Lanka.",
            particularites = "Inclusioni di rutilo a forma di seta che possono produrre un asterismo (zaffiro stellato).",
            lithotherapie = "Pietra di saggezza fin dall'antichità, lo zaffiro blu è ritenuto favorire la chiarezza mentale, la lealtà e la ricerca della verità."
        ),
        "saphir-auvergne" to GemTranslation(
            nom = "Zaffiro d'Alvernia",
            descriptionCourte = "Un corindone francese dalla tonalità blu-violetto intensa, estratto dai terreni vulcanici dell'Alvernia.",
            descriptionLongue = "Estratti dai terreni vulcanici del Massiccio Centrale, in particolare intorno a Espaly-Saint-Marcel presso Le Puy-en-Velay, gli zaffiri d'Alvernia sono una varietà francese di corindone dalla tonalità blu-violetto intensa. Come altri zaffiri di origine basaltica, si distinguono per un colore molto intenso ma con cristalli generalmente piccoli, raramente sfaccettabili oltre un carato. Estratti storicamente nel XIX secolo, restano oggi una curiosità ricercata da collezionisti e appassionati di gemmologia francese, più che una fonte commerciale di volume.",
            particularites = "Cristalli generalmente piccoli (raramente oltre un carato una volta tagliati), dal colore blu-violetto molto intenso tipico degli zaffiri di origine basaltica.",
            lithotherapie = "Come gli altri zaffiri, lo zaffiro d'Alvernia è tradizionalmente associato alla saggezza e alla lucidità mentale; la sua origine francese ne fa una pietra particolarmente apprezzata dai collezionisti legati al patrimonio mineralogico nazionale."
        ),
        "aigue-marine" to GemTranslation(
            nom = "Acquamarina",
            descriptionCourte = "«Acqua di mare» cristallina.",
            descriptionLongue = "Il suo nome, derivato dal latino «aqua marina», evoca il suo colore dal blu pallido al blu-verde che ricorda l'acqua di mare. Il berillo blu si distingue per la sua grande purezza, con pochissime inclusioni visibili a occhio nudo.",
            particularites = "Spesso riscaldata per attenuare la componente verde e intensificare il blu.",
            lithotherapie = "Pietra dei marinai, l'acquamarina è tradizionalmente associata alla serenità, al coraggio e a una comunicazione pacata, in particolare durante i viaggi."
        ),
        "tanzanite" to GemTranslation(
            nom = "Tanzanite",
            descriptionCourte = "Un'unica fonte al mondo, ai piedi del Kilimangiaro.",
            descriptionLongue = "Scoperta nel 1967, la tanzanite esiste solo nella zona di Merelani, in Tanzania. Il suo forte tricroismo fa apparire blu, viola e bordeaux a seconda dell'angolo di osservazione, prima che il riscaldamento standard stabilizzi la tonalità blu-violetto ricercata.",
            particularites = "Giacimento unico e in via di esaurimento, considerata una pietra da investimento.",
            lithotherapie = "La tanzanite è ritenuta accompagnare la trasformazione interiore e favorire un sereno risveglio spirituale."
        ),
        "lapis-lazuli" to GemTranslation(
            nom = "Lapislazzuli",
            descriptionCourte = "Blu profondo costellato d'oro, utilizzato fin dall'antichità.",
            descriptionLongue = "Il lapislazzuli è una roccia composta principalmente da lazurite, associata a pirite (inclusioni dorate) e calcite (venature bianche). Utilizzato nell'antico Egitto e macinato per il pigmento «blu oltremare», adorna gioielli e oggetti d'arte da millenni.",
            particularites = "Le inclusioni dorate di pirite, distribuite uniformemente, sono una garanzia di qualità.",
            lithotherapie = "Pietra di saggezza e di verità fin dall'antico Egitto, il lapislazzuli è ritenuto rafforzare la fiducia in sé stessi e la chiarezza di giudizio."
        ),
        "turquoise" to GemTranslation(
            nom = "Turchese",
            descriptionCourte = "Blu-verde emblematico, venato di matrice.",
            descriptionLongue = "Utilizzato fin dall'antico Egitto e sacro per numerose culture amerindie, il turchese deve il suo blu al rame. Poroso e tenero, viene spesso stabilizzato tramite impregnazione di resina per resistere all'uso in gioielleria.",
            particularites = "Matrice venata caratteristica; poroso, sensibile ai cosmetici e ai prodotti chimici.",
            lithotherapie = "Pietra di protezione da millenni, il turchese è ritenuto favorire la serenità, la comunicazione sincera e la protezione durante i viaggi."
        ),
        "spinelle-bleu" to GemTranslation(
            nom = "Spinello blu",
            descriptionCourte = "Blu intenso, talvolta colorato dal cobalto.",
            descriptionLongue = "Più raro dello spinello rosso, lo spinello blu deve la sua tonalità più pregiata a tracce di cobalto, che produce un colore blu profondo e vellutato sotto luce incandescente.",
            particularites = "Generalmente non trattato, a differenza di molti zaffiri blu.",
            lithotherapie = "Lo spinello blu è associato alla distensione emotiva e al rinnovamento dopo un periodo di tensione."
        ),
        "paraiba-tourmaline" to GemTranslation(
            nom = "Tormalina Paraíba",
            descriptionCourte = "Blu-verde «neon» elettrico, unico nel regno minerale.",
            descriptionLongue = "Scoperta nel 1989 nello stato brasiliano di Paraíba, questa tormalina deve il suo inedito blu-verde elettrico a tracce di rame e manganese. Giacimenti simili sono stati successivamente trovati in Mozambico e Nigeria. È una delle gemme colorate più costose al mondo.",
            particularites = "Colore «neon» dovuto al rame, mai osservato nelle altre tormaline.",
            lithotherapie = "La tormalina Paraíba è ritenuta stimolare una gioia profonda e una vitalità rinnovata, in eco al suo colore sfolgorante."
        ),
        "apatite-bleue" to GemTranslation(
            nom = "Apatite blu neon",
            descriptionCourte = "Blu turchese elettrico poco conosciuto dal grande pubblico.",
            descriptionLongue = "L'apatite blu neon, scoperta in Madagascar negli anni '90, offre una tonalità turchese molto saturata vicina a quella della tormalina Paraíba, per un budget molto più accessibile. La sua relativa tenerezza ne limita l'uso a gioielli protetti.",
            particularites = "Durezza moderata (5): da riservare a orecchini e ciondoli piuttosto che ad anelli.",
            lithotherapie = "L'apatite blu neon è associata alla motivazione e alla chiarezza degli obiettivi personali, un sostegno per ritrovare il proprio centro."
        ),
        "cyanite" to GemTranslation(
            nom = "Cianite (distene)",
            descriptionCourte = "Durezza variabile secondo l'asse del cristallo.",
            descriptionLongue = "La cianite (o distene, «due resistenze» in greco) è celebre per la sua anisotropia di durezza: 4,5 nel senso della lunghezza del cristallo, 6,5 perpendicolarmente. Il suo blu profondo ricorda talvolta lo zaffiro, per un prezzo molto più accessibile.",
            particularites = "Durezza anisotropa che rende delicata la lavorazione; sfaldatura perfetta in una direzione.",
            lithotherapie = "La cianite (distene) è ritenuta favorire l'allineamento interiore e una comunicazione fluida tra il cuore e la ragione."
        ),
        "benitoite" to GemTranslation(
            nom = "Benitoite",
            descriptionCourte = "Pietra ufficiale della California, dispersione notevole.",
            descriptionLongue = "Scoperta nel 1907 nella contea di San Benito, in California, la benitoite fluoresce di un blu vivo sotto raggi UV e presenta una dispersione superiore a quella del diamante. Il giacimento originario resta, più di un secolo dopo, la fonte quasi unica al mondo di qualità gemma.",
            particularites = "Fluorescenza blu vivo sotto UV; giacimento di qualità gemma quasi unico al mondo.",
            lithotherapie = "Minerale raro e prezioso, la benitoite è associata in litoterapia all'elevazione spirituale e alla chiarezza di coscienza."
        ),
        "jeremejevite" to GemTranslation(
            nom = "Jeremejevite",
            descriptionCourte = "Borato di alluminio di estrema rarità, dal blu pallido all'incolore.",
            descriptionLongue = "Descritta nel 1883 in Siberia e a lungo introvabile in qualità gemma, la jeremejevite è stata riscoperta in quantità sfruttabile solo in Namibia negli anni '70. Il suo blu pallido limpido e la sua rarità ne fanno una pietra da collezione apprezzata dagli intenditori.",
            particularites = "La maggior parte della produzione gemma mondiale proviene da un unico massiccio namibiano.",
            lithotherapie = "La jeremejevite, estremamente rara, è associata all'apertura mentale e alla connessione con una forma di saggezza superiore."
        ),
        "violane" to GemTranslation(
            nom = "Violano",
            descriptionCourte = "Una varietà massiva e compatta di diopside, blu-violetto profondo.",
            descriptionLongue = "Il violano è una varietà massiva e compatta di diopside, di un blu-violetto intenso vicino a quello di alcune azzurriti, colorato da inclusioni di magnetite. Sempre lavorato a cabochon o come oggetto lucidato.",
            particularites = "Giacimento tipo e storico nella Valle d'Aosta italiana; sempre lavorato a cabochon.",
            lithotherapie = "Il violano, varietà viola di diopside, è associato alla calma mentale e all'introspezione, un sostegno per la meditazione."
        ),
        "saphir-violet" to GemTranslation(
            nom = "Zaffiro viola",
            descriptionCourte = "Un viola profondo al confine tra lo zaffiro blu e il rubino.",
            descriptionLongue = "Lo zaffiro viola deve la sua tonalità a una combinazione di tracce di ferro, titanio e cromo, situandosi al confine cromatico tra lo zaffiro blu e il rubino. Alcune pietre presentano un cambiamento di colore parziale a seconda dell'illuminazione.",
            particularites = "Può presentare un lieve cambiamento di colore tra luce diurna e luce incandescente.",
            lithotherapie = "Lo zaffiro viola è ritenuto favorire la spiritualità e l'intuizione, un sostegno per i periodi di interrogativo interiore."
        ),
        "purpurite" to GemTranslation(
            nom = "Purpurite",
            descriptionCourte = "Un viola-rosso opaco intenso, rara pietra ornamentale di fosfato.",
            descriptionLongue = "La purpurite deve il suo nome al colore porpora intenso, risultato dell'alterazione di fosfati di manganese e ferro. Opaca e relativamente tenera, viene lavorata a cabochon per la gioielleria e gli oggetti d'arte.",
            particularites = "Il colore può attenuarsi in superficie con l'esposizione prolungata alla luce; da proteggere.",
            lithotherapie = "La purpurite è associata alla trasformazione personale e alla forza interiore nei periodi di cambiamento."
        ),
        "hackmanite" to GemTranslation(
            nom = "Hackmanite",
            descriptionCourte = "Una pietra camaleonte che si tinge di rosa sotto UV per poi sbiadire alla luce.",
            descriptionLongue = "La hackmanite è una varietà di sodalite tenebrescente: esposta ai raggi UV, sviluppa una tonalità rosa-violetta che si attenua poi progressivamente alla luce del giorno, un fenomeno reversibile affascinante e unico tra le gemme.",
            particularites = "Fenomeno di tenebrescenza reversibile: il colore varia in base alla recente esposizione ai raggi UV o alla luce.",
            lithotherapie = "L'hackmanite è ritenuta stimolare l'intuizione e offrire una forma di protezione energetica, in particolare durante la meditazione."
        ),
        "lepidolite" to GemTranslation(
            nom = "Lepidolite",
            descriptionCourte = "La mica lilla al litio, spesso associata alla tormalina rosa.",
            descriptionLongue = "La lepidolite è una mica ricca di litio, dalla caratteristica tonalità lilla-malva, che si trova frequentemente in pegmatite accanto alla tormalina rosa e alla kunzite, con cui condivide la stessa chimica al litio.",
            particularites = "Troppo tenera e sfaldabile per la gioielleria a taglio sfaccettato; utilizzata a cabochon, in perline e oggetti decorativi.",
            lithotherapie = "Ricca di litio naturale, la lepidolite è tradizionalmente ritenuta capace di alleviare lo stress e l'ansia e di favorire un sonno tranquillo."
        ),
        "stichtite" to GemTranslation(
            nom = "Stichtite",
            descriptionCourte = "Un viola-rosa lilla, spesso intrecciato con serpentino verde (atlantasite).",
            descriptionLongue = "La stichtite forma masse viola-rosa lilla, spesso intercresciute con serpentino verde a formare l'« atlantasite », una combinazione molto ricercata per cabochon e oggetti ornamentali.",
            particularites = "Estremamente tenera: riservata a cabochon e oggetti decorativi poco esposti a urti.",
            lithotherapie = "La stichtite è associata alla compassione verso se stessi e gli altri, favorendo il perdono e la serenità emotiva."
        ),
        "amethyste" to GemTranslation(
            nom = "Ametista",
            descriptionCourte = "La pietra della temperanza.",
            descriptionLongue = "L'ametista deve il suo colore viola a tracce di ferro combinate a un'irradiazione naturale. Abbondante e accessibile, è stata comunque indossata dalla nobiltà e dal clero per secoli, simbolo di sobrietà e spiritualità.",
            particularites = "Può scolorire in caso di esposizione prolungata alla luce solare.",
            lithotherapie = "L'ametista è una delle pietre più rinomate in litoterapia per alleviare lo stress, favorire un sonno sereno e sostenere la meditazione e la spiritualità."
        ),
        "spinelle-violet" to GemTranslation(
            nom = "Spinello viola",
            descriptionCourte = "Resistenza e brillantezza per un'alternativa duratura.",
            descriptionLongue = "Lo spinello viola unisce una buona durezza all'assenza di sfaldatura, il che ne fa un'alternativa molto resistente all'ametista o allo zaffiro viola, con una lucentezza vitrea particolarmente vivace.",
            particularites = "Generalmente non trattato.",
            lithotherapie = "Lo spinello viola è associato al rinnovamento spirituale e alla serenità interiore."
        ),
        "iolite" to GemTranslation(
            nom = "Iolite",
            descriptionCourte = "Lo « zaffiro dei Vichinghi ».",
            descriptionLongue = "La iolite deve il suo nome al greco « ios » (viola). Il suo spettacolare pleocroismo fa passare il colore dal blu-violetto al giallo pallido quasi incolore a seconda dell'angolo di osservazione, una particolarità che i navigatori vichinghi avrebbero utilizzato per orientarsi.",
            particularites = "Pleocroismo tricroico molto marcato, determinante per l'orientamento del taglio.",
            lithotherapie = "Utilizzata dai navigatori vichinghi per orientarsi, la iolite è ritenuta capace di rafforzare l'intuizione e la lucidità visionaria nelle scelte di vita."
        ),
        "grenat-rhodolite-violet" to GemTranslation(
            nom = "Granato rodolite violaceo",
            descriptionCourte = "Tonalità porpora che cambia a seconda dell'illuminazione.",
            descriptionLongue = "Alcune rodoliti presentano una dominante porpora-violacea particolarmente marcata sotto luce naturale, offrendo un'alternativa economica alle pietre viola più rare.",
            particularites = "Colore stabile, mai trattato.",
            lithotherapie = "Questa varietà violacea di rodolite è associata all'equilibrio tra passione e serenità emotiva."
        ),
        "sugilite" to GemTranslation(
            nom = "Sugilite",
            descriptionCourte = "Viola intenso, resa popolare negli anni '70.",
            descriptionLongue = "Descritta in Giappone nel 1944 e poi resa popolare dai giacimenti sudafricani scoperti negli anni '70, la sugilite offre un colore dal viola al porpora profondo, da opaco a traslucido, tagliata a cabochon.",
            particularites = "Sempre tagliata a cabochon; il principale giacimento sudafricano è oggi esaurito.",
            lithotherapie = "La sugilite è ritenuta offrire protezione spirituale e conforto nei periodi di lutto o di grande stanchezza emotiva."
        ),
        "charoite" to GemTranslation(
            nom = "Charoite",
            descriptionCourte = "Un unico giacimento in Siberia.",
            descriptionLongue = "Descritta solo nel 1978, la charoite è conosciuta da un unico giacimento sulle rive del fiume Chara, in Siberia. Il suo motivo vorticoso viola e bianco, dovuto all'intreccio di fibre cristalline, ne fa una pietra ornamentale immediatamente riconoscibile.",
            particularites = "Giacimento unico al mondo; motivo vorticoso caratteristico, sempre tagliata a cabochon.",
            lithotherapie = "La charoite è associata alla profonda trasformazione interiore e al coraggio necessario per affrontare il cambiamento."
        ),
        "taaffeite" to GemTranslation(
            nom = "Taaffeite",
            descriptionCourte = "Il primo minerale scoperto in una pietra già tagliata.",
            descriptionLongue = "Identificata nel 1945 dal gemmologo Richard Taaffe in una pietra già sfaccettata e erroneamente classificata come spinello, la taaffeite resta una delle gemme più rare al mondo, in delicate tonalità dal malva al lilla.",
            particularites = "A lungo confusa con lo spinello; si distingue per una doppia rifrazione che lo spinello non possiede.",
            lithotherapie = "Minerale estremamente raro, la taaffeite è associata in litoterapia al risveglio della coscienza e alla singolarità del cammino personale."
        ),
        "axinite" to GemTranslation(
            nom = "Assinite",
            descriptionCourte = "Cristalli a lama d'ascia, forte pleocroismo.",
            descriptionLongue = "Il suo nome deriva dal greco « axine » (ascia), in riferimento alla forma appuntita e appiattita dei suoi cristalli. L'assinite presenta un forte pleocroismo dal bruno-violetto al giallo-verde a seconda dell'angolo di osservazione, apprezzata dai collezionisti di pietre rare.",
            particularites = "Pleocroismo tricroico marcato; cristalli storicamente descritti in Francia (Delfinato).",
            lithotherapie = "L'assinite è ritenuta favorire il radicamento e la concentrazione, un sostegno per restare centrati nei periodi agitati."
        ),
        "cobaltocalcite" to GemTranslation(
            nom = "Cobaltocalcite",
            descriptionCourte = "Un rosa confetto vivace, varietà di calcite colorata dal cobalto.",
            descriptionLongue = "La cobaltocalcite (calcite cobaltifera) mostra un rosa vivo ed elettrico dovuto a tracce di cobalto, formando croste botrioidali molto ricercate dai collezionisti. La sua estrema tenerezza esclude qualsiasi uso gioielliero corrente.",
            particularites = "Estremamente tenera e sensibile agli acidi come ogni calcite; pietra esclusivamente da collezione.",
            lithotherapie = "La cobaltocalcite è associata all'amore per se stessi e alla tenerezza, un dolce sostegno emotivo nei periodi delicati."
        ),
        "thulite" to GemTranslation(
            nom = "Tulite",
            descriptionCourte = "La varietà rosa della zoisite, cugina della tanzanite blu.",
            descriptionLongue = "La tulite è la varietà dal rosa al rosso-rosa della zoisite, colorata dal manganese — lo stesso minerale della tanzanite, ma senza il trattamento termico che rivela il blu-violetto di quest'ultima. Scoperta in Norvegia, le deve il suo nome (Thule).",
            particularites = "Quasi sempre opaca e lavorata a cabochon; le pietre sfaccettate trasparenti sono rare.",
            lithotherapie = "La tulite è ritenuta ravvivare la gioia e la vitalità affettiva, un sostegno per ritrovare le proprie emozioni positive."
        ),
        "rhodonite" to GemTranslation(
            nom = "Rodonite",
            descriptionCourte = "Un rosa profondo venato di nero manganesifero.",
            descriptionLongue = "La rodonite offre un colore dal rosa al rosso-rosa intenso, attraversato da venature nere di ossidi di manganese che le conferiscono un aspetto marmorizzato caratteristico. Pietra nazionale della Russia, ha storicamente ornato i palazzi imperiali.",
            particularites = "Pietra nazionale della Russia; le venature nere di manganese ne costituiscono un motivo di identificazione caratteristico.",
            lithotherapie = "La rodonite è tradizionalmente associata al perdono e alla guarigione delle ferite affettive, in particolare dopo una separazione."
        ),
        "topaze-rose" to GemTranslation(
            nom = "Topazio rosa",
            descriptionCourte = "Il rosa naturale più raro del topazio, storicamente estratto in Pakistan.",
            descriptionLongue = "Il topazio rosa naturale, non trattato, è molto più raro del topazio blu o incolore. Lo storico giacimento di Katlang, in Pakistan, ha fornito alcune delle pietre più belle, dalla delicata tonalità rosa pesca.",
            particularites = "Il rosa naturale non trattato è raro; si distingue dal topazio rosa ottenuto tramite trattamento termico di pietre brune.",
            lithotherapie = "Il topazio rosa è ritenuto favorire la dolcezza nelle relazioni e aprire il cuore all'amore sincero."
        ),
        "quartz-rose" to GemTranslation(
            nom = "Quarzo rosa",
            descriptionCourte = "Il quarzo rosa pastello, pietra dell'amore in tutte le tradizioni.",
            descriptionLongue = "Il quarzo rosa, colorato da tracce di titanio, manganese o da microscopiche inclusioni fibrose di dumortierite, è associato all'amore e alla dolcezza nella maggior parte delle culture. I cristalli sfaccettabili trasparenti sono rari; la materia massiva traslucida è la più comune.",
            particularites = "Alcune pietre presentano un asterismo a sei raggi (quarzo rosa stellato) tagliato a cabochon.",
            lithotherapie = "Pietra dell'amore incondizionato per eccellenza, il quarzo rosa è ritenuto lenire le ferite del cuore e favorire la tenerezza verso se stessi e gli altri."
        ),
        "phosphosiderite" to GemTranslation(
            nom = "Fosfosiderite",
            descriptionCourte = "Un rosa-viola tenue in croste mammellonari, cugina della variscite.",
            descriptionLongue = "La fosfosiderite forma croste mammellonari dal rosa lilla al violaceo, chimicamente simile alla variscite verde ma colorata dal ferro. Sempre lavorata a cabochon per rivelare il suo riflesso setoso.",
            particularites = "Tenerezza simile a quella della variscite; sempre lavorata a cabochon.",
            lithotherapie = "La fosfosiderite è associata al lasciar andare e alla dolcezza interiore, un sostegno durante la meditazione."
        ),
        "morganite" to GemTranslation(
            nom = "Morganite",
            descriptionCourte = "Rosa tenue tendente al pesca, denominata nel 1911.",
            descriptionLongue = "Battezzata in onore del finanziere e collezionista J.P. Morgan dal gemmologo George Kunz, la morganite offre una delicata tonalità dal rosa al pesca dovuta al manganese. Molto pura, viene spesso tagliata in pietre grandi e spettacolari.",
            particularites = "Spesso sottoposta a trattamento termico per attenuare una componente arancione e rivelare un rosa puro.",
            lithotherapie = "La morganite è ritenuta aprire il cuore alla compassione e all'amore per se stessi, alleviando l'ansia affettiva."
        ),
        "kunzite" to GemTranslation(
            nom = "Kunzite",
            descriptionCourte = "Pleocroismo marcato, pietra delicata.",
            descriptionLongue = "Scoperta nel 1902 e battezzata in onore del gemmologo George Frederick Kunz, la kunzite mostra un seducente rosa lilla. È tuttavia sensibile alla luce prolungata e agli shock termici, da riservare a un uso occasionale.",
            particularites = "Sfaldatura netta in due direzioni; da proteggere dalla luce diretta prolungata.",
            lithotherapie = "La kunzite è associata all'amore incondizionato e a una profonda serenità emotiva, un sostegno per liberarsi dalle tensioni accumulate."
        ),
        "saphir-rose" to GemTranslation(
            nom = "Zaffiro rosa",
            descriptionCourte = "Al confine tra rubino e zaffiro.",
            descriptionLongue = "Colorato dal cromo come il rubino ma in concentrazione minore, lo zaffiro rosa si colloca al limite convenzionale del rubino: oltre una certa saturazione, la pietra viene riclassificata come rubino.",
            particularites = "Il confine tra rubino e zaffiro rosa resta dibattuto a seconda dei laboratori gemmologici.",
            lithotherapie = "Lo zaffiro rosa è ritenuto favorire l'amore sincero e l'armonia nelle relazioni affettive."
        ),
        "tourmaline-rose" to GemTranslation(
            nom = "Tormalina rosa",
            descriptionCourte = "Manganese per una tonalità tenue.",
            descriptionLongue = "Meno satura della rubellite, la tormalina rosa offre tonalità delicate che vanno dal rosa pallido al rosa confetto, spesso associate a cristalli bicolori o tricolori caratteristici del gruppo.",
            particularites = "Cristalli spesso zonati, all'origine delle tormaline bicolori.",
            lithotherapie = "La tormalina rosa è associata alla tenerezza e alla guarigione delle ferite emotive legate all'amore e all'attaccamento."
        ),
        "rhodochrosite" to GemTranslation(
            nom = "Rodocrosite",
            descriptionCourte = "Bande concentriche rosa e bianche.",
            descriptionLongue = "Riconoscibile per i suoi motivi concentrici rosa e bianchi che ricordano gli anelli di crescita di un albero, la rodocrosite è una pietra decorativa e da collezione molto apprezzata, ma troppo fragile per un uso quotidiano in anello.",
            particularites = "Molto fragile e sensibile agli acidi; riservata a pezzi da collezione o pendenti protetti.",
            lithotherapie = "La rodocrosite è ritenuta favorire l'amore per se stessi e la guarigione del bambino interiore, un sostegno nel lavoro emotivo profondo."
        ),
        "saphir-blanc" to GemTranslation(
            nom = "Zaffiro bianco",
            descriptionCourte = "Il corindone privo di tracce coloranti, alternativa discreta al diamante.",
            descriptionLongue = "Privo delle tracce metalliche che colorano il rubino o lo zaffiro blu, lo zaffiro bianco (o « leucozaffiro ») offre una brillantezza vicina a quella del diamante a un prezzo molto inferiore, a lungo utilizzato come pietra sostitutiva nell'orologeria e nella gioielleria.",
            particularites = "Dispersione inferiore a quella del diamante, ma durezza quasi identica; eccellente resistenza all'usura quotidiana.",
            lithotherapie = "Lo zaffiro bianco è ritenuto favorire la lucidità mentale e la purezza d'intenti nelle decisioni importanti."
        ),
        "topaze-blanche" to GemTranslation(
            nom = "Topazio bianco",
            descriptionCourte = "Il topazio nella sua forma più pura e più comune, incolore e limpido.",
            descriptionLongue = "Il topazio incolore è in realtà il colore più diffuso in natura per questa specie — i topazi blu del commercio ne derivano peraltro quasi sempre tramite trattamento. Limpido e brillante, funge anche da pietra sostitutiva economica del diamante.",
            particularites = "Materia prima più abbondante per la produzione di topazio blu trattato tramite irraggiamento.",
            lithotherapie = "Il topazio bianco è associato alla chiarezza mentale e alla ricerca della verità nelle proprie scelte di vita."
        ),
        "hambergite" to GemTranslation(
            nom = "Hambergite",
            descriptionCourte = "Una gemma incolore di estrema rarità, tanto fragile quanto brillante.",
            descriptionLongue = "L'hambergite è una gemma incolore o appena tinta, rara e brillante, ma di estrema fragilità a causa di una sfaldatura perfetta che ne fa una sfida temibile per i lapidari — una delle pietre più raramente viste sul mercato.",
            particularites = "Sfaldatura perfetta che rende il taglio e l'uso in gioielleria particolarmente rischiosi; pietra da collezione.",
            lithotherapie = "L'hambergite, minerale raro, è associata in litoterapia alla chiarezza mentale e alla concentrazione."
        ),
        "petalite" to GemTranslation(
            nom = "Petalite",
            descriptionCourte = "Un minerale di litio raramente sfaccettato, discreto e limpido.",
            descriptionLongue = "La petalite, importante fonte di litio industriale, produce occasionalmente cristalli gemma incolori o leggermente colorati, tagliati per i collezionisti più che per la gioielleria di largo consumo.",
            particularites = "Estratta soprattutto come minerale di litio; le qualità gemma sfaccettabili sono aneddotiche.",
            lithotherapie = "La petalite è ritenuta favorire una profonda serenità, particolarmente apprezzata per accompagnare la meditazione."
        ),
        "phenakite" to GemTranslation(
            nom = "Fenacite",
            descriptionCourte = "Una gemma incolore così limpida da essere stata a lungo confusa con il quarzo o il diamante.",
            descriptionLongue = "Il nome della fenacite (dal greco « impostore ») deriva dalla sua ingannevole somiglianza con il quarzo o persino con il diamante allo stato grezzo. Rara e dotata di una bella brillantezza una volta sfaccettata, resta apprezzata soprattutto dai collezionisti esperti.",
            particularites = "Il suo nome greco significa « impostore », in riferimento alla confusione storica con il quarzo.",
            lithotherapie = "La fenacite è associata al risveglio della coscienza e a una grande chiarezza spirituale, riservata alle pratiche meditative avanzate."
        ),
        "bytownite" to GemTranslation(
            nom = "Bytownite",
            descriptionCourte = "Un feldspato raramente sfaccettabile, polo calcico della serie dei plagioclasi.",
            descriptionLongue = "La bytownite, ricca di calcio all'interno della serie dei plagioclasi (tra labradorite e anortite), forma eccezionalmente cristalli limpidi sufficientemente puri da essere sfaccettati, principalmente in Congo e in India.",
            particularites = "Membro calcico della serie dei plagioclasi, tra la labradorite e l'anortite pura.",
            lithotherapie = "La bytownite è ritenuta offrire un radicamento luminoso, tra dolce protezione e chiarezza mentale."
        ),
        "hyalite" to GemTranslation(
            nom = "Ialite",
            descriptionCourte = "Un opale incolore e trasparente che si illumina di verde fluorescente sotto raggi UV.",
            descriptionLongue = "La ialite è un opale non prezioso, incolore e perfettamente trasparente in strati sottili, celebre per la sua fluorescenza verde brillante sotto luce ultravioletta dovuta a tracce di uranio — uno spettacolo apprezzato dagli appassionati di minerali fluorescenti.",
            particularites = "Fluorescenza verde brillante sotto UV dovuta a tracce di uranio, priva di opalescenza a differenza dell'opale prezioso.",
            lithotherapie = "Questa varietà di opale incolore è associata alla purezza e alla leggerezza di spirito."
        ),
        "anhydrite" to GemTranslation(
            nom = "Anidrite",
            descriptionCourte = "Il solfato di calcio privo di acqua, cugino secco del gesso, raramente tagliato.",
            descriptionLongue = "L'anidrite, chimicamente simile al gesso ma priva di acqua di cristallizzazione, si presenta in tonalità dall'incolore al blu pallido o violaceo. La sua tenerezza e la sua sfaldatura la riservano a un uso da collezione confidenziale.",
            particularites = "Si idrata lentamente trasformandosi in gesso a contatto prolungato con l'acqua, un fenomeno naturale di trasformazione minerale.",
            lithotherapie = "L'anidrite è ritenuta apportare struttura e chiarezza nell'organizzazione dei propri pensieri e della vita quotidiana."
        ),
        "baryte" to GemTranslation(
            nom = "Barite",
            descriptionCourte = "Un minerale denso e tenero, raramente sfaccettato ma spettacolare nei cristalli.",
            descriptionLongue = "La barite (solfato di bario) deve il suo nome alla sua notevole densità per un minerale non metallico. I suoi cristalli tabulari, spesso dall'incolore al giallo miele, vengono occasionalmente sfaccettati per i collezionisti nonostante la loro grande fragilità.",
            particularites = "Densità eccezionalmente elevata per un minerale non metallico, utilizzata come criterio di identificazione.",
            lithotherapie = "La barite è associata al radicamento e alla stabilità emotiva, un sostegno nei periodi di cambiamento."
        ),
        "aragonite" to GemTranslation(
            nom = "Aragonite",
            descriptionCourte = "Il polimorfo del calcare che forma anche le perle e i coralli.",
            descriptionLongue = "L'aragonite è il polimorfo ortorombico del carbonato di calcio — la stessa sostanza che compone le perle, le conchiglie e il corallo. I suoi cristalli terrestri, spesso dall'incolore al giallo pallido, sono soprattutto collezionati allo stato grezzo.",
            particularites = "Instabile nel lunghissimo termine: si trasforma lentamente in calcite, il suo polimorfo più stabile.",
            lithotherapie = "L'aragonite è ritenuta favorire il radicamento e la pazienza, aiutando ad accettare il ritmo naturale delle cose."
        ),
        "calcite" to GemTranslation(
            nom = "Calcite",
            descriptionCourte = "Il minerale più comune della crosta terrestre, occasionalmente sfaccettato.",
            descriptionLongue = "La calcite è uno dei minerali più diffusi al mondo, con una straordinaria diversità di forme cristalline. Troppo tenera per un uso quotidiano, viene comunque sfaccettata dai collezionisti per la sua spettacolare birifrangenza (sdoppiamento dell'immagine attraverso la pietra).",
            particularites = "Birifrangenza estrema: un oggetto visto attraverso un cristallo di calcite limpido appare sdoppiato.",
            lithotherapie = "La calcite è tradizionalmente utilizzata per purificare le energie circostanti e apportare chiarezza mentale."
        ),
        "cerusite" to GemTranslation(
            nom = "Cerussite",
            descriptionCourte = "Un minerale di piombo dalla dispersione spettacolare, raro come pietra sfaccettata.",
            descriptionLongue = "La cerussite, minerale di piombo, possiede una dispersione ottica superiore a quella del diamante, producendo notevoli lampi di fuoco una volta sfaccettata. La sua densità molto elevata e la sua grande fragilità ne fanno una gemma esclusivamente da collezione.",
            particularites = "Dispersione ottica superiore a quella del diamante; densità molto elevata caratteristica del piombo.",
            lithotherapie = "La cerussite è associata al radicamento e a una trasformazione interiore dolce."
        ),
        "montebrasite" to GemTranslation(
            nom = "Montebrasite",
            descriptionCourte = "Una gemma discreta al litio, cugina dell'ambligonite.",
            descriptionLongue = "La montebrasite, stretta parente dell'ambligonite da cui si distingue solo per il contenuto di idrossile, offre pietre dall'incolore al giallo pallido, sfaccettate soprattutto per gli appassionati di rarità litinifere.",
            particularites = "Giacimento tipo ed eponimo nella Creuse, in Francia, scoperto nel XIX secolo.",
            lithotherapie = "La montebrasite è ritenuta favorire la chiarezza mentale e il discernimento di fronte alle scelte importanti."
        ),
        "diamant" to GemTranslation(
            nom = "Diamante",
            descriptionCourte = "La gemma più dura conosciuta.",
            descriptionLongue = "Formatosi ad altissima pressione e temperatura nel mantello terrestre, il diamante è composto da carbonio puro cristallizzato. La sua durezza massima, la sua forte dispersione (il « fuoco ») e la sua lucentezza adamantina ne fanno la pietra di riferimento dell'alta gioielleria, valutata secondo le « 4C »: carato, colore, purezza (clarity) e taglio (cut).",
            particularites = "Unica gemma con durezza 10; certificazione obbligatoria (GIA, HRD...) per le pietre di rilievo.",
            lithotherapie = "Simbolo di forza e purezza da sempre, il diamante è ritenuto amplificare le energie circostanti e rafforzare la chiarezza d'intenti e la fiducia in se stessi."
        ),
        "zircon-blanc" to GemTranslation(
            nom = "Zircone bianco",
            descriptionCourte = "Forte dispersione, a lungo utilizzato come sostituto del diamante.",
            descriptionLongue = "Da non confondere con la zirconia cubica (materiale sintetico), lo zircone è una gemma naturale la cui forte dispersione luminosa rivaleggia con quella del diamante, il che ne ha fatto un apprezzato sostituto storico.",
            particularites = "Spesso sottoposto a trattamento termico per ottenere l'incolore a partire da zircone bruno; gli spigoli delle sfaccettature appaiono talvolta sdoppiati.",
            lithotherapie = "Lo zircone bianco è associato alla chiarezza mentale e alla purezza d'intenti, un'alternativa luminosa al diamante."
        ),
        "goshenite" to GemTranslation(
            nom = "Goshenite (berillo bianco)",
            descriptionCourte = "La varietà incolore, rara, del berillo.",
            descriptionLongue = "Meno ricercata commercialmente rispetto alle sue cugine colorate (smeraldo, acquamarina, morganite), la goshenite è tuttavia la forma più pura del berillo, totalmente priva di elementi cromogeni.",
            particularites = "Storicamente utilizzata come lenti per occhiali prima dell'uso del vetro ottico.",
            lithotherapie = "La goshenite (berillo incolore) è ritenuta favorire la chiarezza mentale e aiutare a vedere le situazioni con obiettività."
        ),
        "cristal-de-roche" to GemTranslation(
            nom = "Cristallo di rocca",
            descriptionCourte = "Il quarzo puro, trasparente e abbondante.",
            descriptionLongue = "Totalmente incolore allo stato puro, il cristallo di rocca è una delle gemme più abbondanti sulla Terra. Fu a lungo utilizzato per tagliare sfere di divinazione e componenti ottici prima dell'era del vetro industriale.",
            particularites = "Grande disponibilità in cristalli di grandi dimensioni, che consente tagli fantasia spettacolari.",
            lithotherapie = "Pietra « maestra » della litoterapia, il cristallo di rocca è ritenuto amplificare le energie, chiarire i pensieri e purificare lo spazio circostante."
        ),
        "danburite" to GemTranslation(
            nom = "Danburite",
            descriptionCourte = "Lucentezza vicina a quella del topazio, poco conosciuta.",
            descriptionLongue = "Scoperta a Danbury (Connecticut) nel XIX secolo, la danburite assomiglia molto al topazio incolore o giallo pallido, ma senza la sua sfaldatura perfetta, il che la rende più facile da tagliare e da indossare quotidianamente.",
            particularites = "Nessuna sfaldatura a differenza del topazio, che spesso imita visivamente.",
            lithotherapie = "La danburite è associata a una grande serenità e al risveglio del cuore, un dolce sostegno per la meditazione."
        ),
        "bois-fossilise" to GemTranslation(
            nom = "Legno fossile",
            descriptionCourte = "Il legno d'albero sostituito atomo per atomo dalla silice, nel corso di milioni di anni.",
            descriptionLongue = "Il legno fossile deriva dalla silicizzazione progressiva di tronchi d'albero sepolti, con il quarzo che sostituisce la materia organica pur conservando la struttura legnosa originaria, anelli di crescita compresi. Levigato, rivela motivi naturali sorprendenti.",
            particularites = "Conserva fedelmente la struttura cellulare del legno originario, talvolta visibile al microscopio.",
            lithotherapie = "Il legno fossile è ritenuto offrire un radicamento profondo e ricordare la pazienza necessaria a ogni trasformazione duratura."
        ),
        "os-fossilise" to GemTranslation(
            nom = "Osso fossile",
            descriptionCourte = "Ossa, talvolta di dinosauri, mineralizzate e levigate a cabochon.",
            descriptionLongue = "L'osso fossile, talvolta proveniente da vere e proprie ossa di dinosauro, si mineralizza attraverso la sostituzione dell'apatite organica con silice o altri minerali, conservando la struttura porosa caratteristica del tessuto osseo, rivelata una volta levigato.",
            particularites = "La struttura porosa cellulare originaria resta visibile una volta levigata la pietra, firma del tessuto osseo fossile.",
            lithotherapie = "Associato al radicamento e alla stabilità, l'osso fossile ricorderebbe l'importanza delle radici e della memoria personale."
        ),
        "kornerupine" to GemTranslation(
            nom = "Kornerupina",
            descriptionCourte = "Una gemma rara dal verde-bruno, con forte pleocroismo, talvolta a cambiamento di colore.",
            descriptionLongue = "La kornerupina presenta un pleocroismo marcato (diverse tonalità visibili a seconda dell'angolo di osservazione, dal verde al bruno-rossastro), e alcune pietre dello Sri Lanka mostrano persino un cambiamento di colore paragonabile a quello dell'alessandrite.",
            particularites = "Pleocroismo tricroico marcato, talvolta accompagnato da un cambiamento di colore a seconda della fonte luminosa.",
            lithotherapie = "La kornerupina, minerale discreto e raro, è associata a un dolce radicamento e alla stabilità interiore."
        ),
        "hyperstene" to GemTranslation(
            nom = "Iperstene",
            descriptionCourte = "Un bruno bronzato cangiante, talvolta chiamato « pietra di velluto ».",
            descriptionLongue = "L'iperstene presenta un caratteristico riflesso bronzo-dorato (schiller) dovuto a inclusioni lamellari interne, che gli vale il soprannome di « pietra di velluto ». Viene per lo più tagliato a cabochon per rivelare questo effetto.",
            particularites = "L'effetto di riflesso bronzo-dorato (schiller) è dovuto a lamelle di essoluzione interne.",
            lithotherapie = "L'iperstene è ritenuto favorire l'introspezione e offrire una forma di protezione energetica discreta."
        ),
        "paesine" to GemTranslation(
            nom = "Paesina",
            descriptionCourte = "Una roccia calcarea i cui motivi naturali evocano paesaggi in miniatura.",
            descriptionLongue = "La paesina, o « pietra paesina » (pietra paesaggio), è una roccia calcarea le cui infiltrazioni di ossidi di ferro e manganese disegnano naturalmente motivi che evocano paesaggi, rovine o orizzonti — un fenomeno pittorico interamente naturale, apprezzato in Toscana sin dal Rinascimento.",
            particularites = "Ogni lastra levigata è unica, come un dipinto naturale formato per capillarità di ossidi metallici.",
            lithotherapie = "Soprannominata « pietra paesaggio », la paesina invita alla contemplazione e a una profonda calma interiore."
        ),
        "enstatite" to GemTranslation(
            nom = "Enstatite",
            descriptionCourte = "Un pirosseno bruno-verde, talvolta con asterismo o effetto occhio di gatto.",
            descriptionLongue = "L'enstatite, polo magnesiaco puro degli ortopirosseni, si presenta in tonalità che vanno dal bruno-verde all'oliva, occasionalmente con un asterismo a quattro raggi o un effetto occhio di gatto quando è tagliata a cabochon.",
            particularites = "Può presentare un asterismo a quattro raggi, più raro del classico asterismo a sei raggi del corindone.",
            lithotherapie = "L'enstatite è associata al radicamento e a una capacità d'azione ponderata e riflessiva."
        ),
        "sphalerite" to GemTranslation(
            nom = "Sfalerite",
            descriptionCourte = "Il minerale di zinco con la dispersione più elevata tra tutte le gemme sfaccettate.",
            descriptionLongue = "La sfalerite, principale minerale di zinco, possiede una dispersione ottica record tra le gemme sfaccettate — superiore a quella del diamante — che produce spettacolari lampi di fuoco. La sua estrema tenerezza ne fa una pietra da collezione più che da uso quotidiano.",
            particularites = "La dispersione più elevata tra tutte le gemme comunemente collezionate, superiore a quella del diamante.",
            lithotherapie = "La sfalerite è ritenuta favorire il radicamento energetico stimolando al contempo la vitalità fisica."
        ),
        "rutile" to GemTranslation(
            nom = "Rutilo",
            descriptionCourte = "Il cristallo responsabile delle inclusioni dorate del quarzo rutilato, raramente sfaccettato da solo.",
            descriptionLongue = "Il rutilo, ossido di titanio dalla lucentezza metallica, è conosciuto soprattutto come minerale incluso nel quarzo rutilato, ma si trova eccezionalmente in cristalli abbastanza puri e trasparenti da poter essere sfaccettati, rivelando una dispersione molto elevata.",
            particularites = "Dispersione ottica molto elevata, vicina a quella del diamante, raramente sfruttata a causa del suo colore scuro.",
            lithotherapie = "Il rutilo è tradizionalmente associato all'amplificazione delle energie e alla chiarezza nel perseguimento dei propri obiettivi."
        ),
        "quartz-fume" to GemTranslation(
            nom = "Quarzo affumicato",
            descriptionCourte = "Bruno translucido, colorato da irradiazione naturale.",
            descriptionLongue = "Il quarzo affumicato deve la sua tonalità bruna a centri di colore indotti dalla radioattività naturale delle rocce incassanti che agisce su tracce di alluminio. Abbondante ed economico, viene spesso riscaldato per essere trasformato in citrino.",
            particularites = "Può essere riscaldato per virare al giallo (citrino) o schiarirsi con un'esposizione prolungata alla luce.",
            lithotherapie = "Il quarzo affumicato è rinomato per le sue potenti virtù di radicamento, che aiutano ad assorbire lo stress e le tensioni quotidiane."
        ),
        "andalousite" to GemTranslation(
            nom = "Andalusite",
            descriptionCourte = "Pleocroismo spettacolare verde-bruno-rosso.",
            descriptionLongue = "L'andalusite deve il suo nome alla regione spagnola in cui fu descritta per la prima volta. Il suo forte pleocroismo tricroico fa apparire, a seconda dell'angolazione, tonalità verde oliva, bruno-rosso e giallo in una stessa pietra, un effetto talvolta soprannominato «alessandrite dei poveri».",
            particularites = "Pleocroismo tricroico molto marcato, l'orientamento del taglio è determinante.",
            lithotherapie = "L'andalusite è associata al radicamento e alla capacità di cambiare prospettiva di fronte alle difficoltà."
        ),
        "sinhalite" to GemTranslation(
            nom = "Sinhalite",
            descriptionCourte = "A lungo confusa con il peridoto bruno.",
            descriptionLongue = "Identificata come specie distinta solo nel 1952, la sinhalite era stata precedentemente classificata per errore tra i peridoti bruni nelle collezioni museali. Il suo nome deriva da «Sinhala», l'antico nome dello Sri Lanka, sua principale fonte.",
            particularites = "Confusa con il peridoto fino al 1952; sempre bruna, mai verde a differenza del peridoto.",
            lithotherapie = "La sinhalite, minerale raro e discreto, è associata alla stabilità interiore e alla perseveranza."
        ),
        "staurotide" to GemTranslation(
            nom = "Staurolite (pietra della croce)",
            descriptionCourte = "Celebre per i suoi geminati a croce.",
            descriptionLongue = "La staurolite forma naturalmente geminati cruciformi chiamati «pietre della croce» o «pietre delle fate», tradizionalmente indossate come amuleto. Raramente sfaccettata a causa della sua frequente opacità, viene soprattutto collezionata allo stato di geminato grezzo.",
            particularites = "Geminati cruciformi caratteristici; raramente sfaccettata, soprattutto collezionata allo stato grezzo.",
            lithotherapie = "Soprannominata pietra della croce, la staurolite è tradizionalmente indossata come talismano di protezione e fortuna."
        ),
        "sphene" to GemTranslation(
            nom = "Sfene (titanite)",
            descriptionCourte = "La dispersione più elevata dopo alcune gemme rarissime.",
            descriptionLongue = "Lo sfene mostra una dispersione ottica (il «fuoco») superiore a quella del diamante, associata a un forte pleocroismo bruno-verde-giallo. La sua relativa tenerezza ne fa una pietra piuttosto riservata alla collezione e ai gioielli poco esposti agli urti.",
            particularites = "Dispersione eccezionale, superiore a quella del diamante; abbastanza tenero e sfaldabile.",
            lithotherapie = "Lo sfene (titanite) è ritenuto stimolare la lucidità mentale e la creatività, un sostegno per i progetti che richiedono precisione e ispirazione."
        ),
        "hematite" to GemTranslation(
            nom = "Ematite",
            descriptionCourte = "L'ossido di ferro metallico grigio-nero, lucidato a specchio fin dall'antichità.",
            descriptionLongue = "L'ematite viene tagliata a cabochon o a intaglio per rivelare una lucentezza metallica grigio-nera quasi speculare. Utilizzata come pietra da sigillo fin dall'antico Egitto, la sua polvere dà peraltro una striscia rossa caratteristica — da cui il suo nome, dal greco «sangue».",
            particularites = "La sua polvere (striscia) è rosso sangue nonostante l'aspetto metallico nero, all'origine del suo nome greco.",
            lithotherapie = "Pietra di radicamento per eccellenza, l'ematite è ritenuta rafforzare la forza interiore e proteggere dalle energie negative circostanti."
        ),
        "magnetite" to GemTranslation(
            nom = "Magnetite",
            descriptionCourte = "Il magnete naturale dell'antichità, conosciuto come pietra di Magnesia.",
            descriptionLongue = "La magnetite è il minerale naturalmente magnetico per eccellenza, conosciuta fin dall'antichità come «pietra calamita» o lodestone. Raramente sfaccettata a causa della sua totale opacità, viene soprattutto lavorata in perle e cabochon.",
            particularites = "Unico minerale naturalmente e fortemente magnetico, proprietà utilizzata fin dall'antichità per la navigazione.",
            lithotherapie = "La magnetite è associata al radicamento e all'equilibrio energetico, spesso utilizzata per ricentrare il corpo e la mente."
        ),
        "quartz-tourmaline" to GemTranslation(
            nom = "Quarzo tormalinato",
            descriptionCourte = "Aghi di tormalina nera imprigionati in un quarzo limpido.",
            descriptionLongue = "Il quarzo tormalinato imprigiona aghi di tormalina nera (schorl) in un cristallo di quarzo altrimenti limpido, creando un motivo grafico sorprendente molto apprezzato sia in litoterapia sia nella gioielleria contemporanea.",
            particularites = "Gli aghi di tormalina restano visibili a occhio nudo, creando un motivo grafico unico per ogni pietra.",
            lithotherapie = "Il quarzo tormalinato unisce le virtù protettive della tormalina nera alla chiarezza amplificatrice del cristallo di rocca."
        ),
        "onyx" to GemTranslation(
            nom = "Onice",
            descriptionCourte = "Bande nere e bianche, spesso tinte.",
            descriptionLongue = "Varietà microcristallina di quarzo della famiglia delle calcedonie, l'onice presenta naturalmente bande nere e bianche. La maggior parte delle pietre commercializzate viene tinta per ottenere un nero uniforme e intenso.",
            particularites = "Tintura artificiale quasi sistematica per omogeneizzare il colore.",
            lithotherapie = "L'onice è tradizionalmente associato alla forza interiore, alla stabilità emotiva e alla protezione dalle energie negative."
        ),
        "spinelle-noir" to GemTranslation(
            nom = "Spinello nero",
            descriptionCourte = "Lucentezza metallica per la gioielleria maschile.",
            descriptionLongue = "Opaco e di un nero profondo, lo spinello nero è particolarmente apprezzato nella gioielleria maschile contemporanea per la sua lucentezza quasi metallica e la sua robustezza nell'uso quotidiano.",
            particularites = "Elevata resistenza ai graffi, adatta ai gioielli indossati quotidianamente.",
            lithotherapie = "Lo spinello nero è ritenuto offrire una solida protezione energetica favorendo al contempo il radicamento."
        ),
        "tourmaline-noire" to GemTranslation(
            nom = "Tormalina nera (Schorl)",
            descriptionCourte = "La varietà di tormalina più comune.",
            descriptionLongue = "Ricco di ferro, lo schorl è di gran lunga la varietà di tormalina più diffusa sulla Terra. Opaco e di un nero corvino, è tradizionalmente associato a virtù protettive in litoterapia.",
            particularites = "Cristalli prismatici spesso striati, talvolta di grandi dimensioni.",
            lithotherapie = "La tormalina nera (schorl) è una delle pietre di protezione più rinomate in litoterapia, ritenuta capace di assorbire le energie negative e rafforzare il radicamento."
        ),
        "obsidienne" to GemTranslation(
            nom = "Ossidiana",
            descriptionCourte = "Vetro naturale dalla frattura tagliente.",
            descriptionLongue = "Formata dal rapido raffreddamento di lava ricca di silice, l'ossidiana è un vetro vulcanico amorfo. La sua frattura concoide estremamente tagliente ne ha fatto uno strumento d'elezione fin dalla preistoria, in particolare per punte di frecce e lame.",
            particularites = "Alcune varietà presentano un effetto cangiante dorato o iridescente (ossidiana arcobaleno).",
            lithotherapie = "L'ossidiana è ritenuta offrire una potente protezione rivelando al contempo le verità nascoste, favorendo una profonda trasformazione interiore."
        ),
        "rubis-etoile" to GemTranslation(
            nom = "Rubino stellato",
            descriptionCourte = "Una stella a sei raggi che scivola sulla superficie del cabochon.",
            descriptionLongue = "Il rubino stellato deve il suo asterismo a sottili inclusioni di rutilo aciculare (la «seta»), orientate secondo la simmetria esagonale del corindone, che riflettono la luce in una stella a sei raggi mobile quando la pietra è tagliata a cabochon.",
            particularites = "Asterismo visibile unicamente a cabochon, mai in taglio sfaccettato; richiede una sorgente luminosa puntiforme.",
            lithotherapie = "Il rubino stellato unisce le virtù protettive del rubino a un potere di guida interiore simboleggiato dalla sua stella."
        ),
        "saphir-etoile" to GemTranslation(
            nom = "Zaffiro stellato",
            descriptionCourte = "Una stella luminosa a sei raggi, spesso in uno zaffiro blu o nero.",
            descriptionLongue = "Come il suo cugino il rubino stellato, lo zaffiro stellato deve il suo asterismo a inclusioni di rutilo in seta. Si trova più spesso in blu o in nero, quest'ultimo tradizionalmente associato alla protezione in diverse culture asiatiche.",
            particularites = "L'asterismo più ricercato presenta sei raggi perfettamente diritti e centrati sulla cupola del cabochon.",
            lithotherapie = "Lo zaffiro stellato è ritenuto portare guida e protezione spirituale, la sua stella simboleggia un cammino da seguire."
        ),
        "saphir-teal" to GemTranslation(
            nom = "Zaffiro teal",
            descriptionCourte = "Un corindone bicolore in cui blu e giallo si combinano in una tonalità blu-verde particolare.",
            descriptionLongue = "Lo zaffiro teal deve il suo caratteristico colore blu-verde alla coesistenza, all'interno di uno stesso cristallo, di zone di crescita blu (ferro e titanio) e gialle (ferro), che si fondono visivamente una volta tagliata la pietra. Questa bicolorazione naturale, più che una tonalità uniforme, ne fa una pietra molto ricercata dagli appassionati di colori insoliti, in particolare nei giacimenti del Montana.",
            particularites = "La bicolorazione blu-gialla, visibile in zone distinte allo stato grezzo, si fonde in una tonalità blu-verde omogenea una volta tagliata e orientata la pietra.",
            lithotherapie = "Lo zaffiro teal è ritenuto favorire l'equilibrio tra ragione e intuizione, la sua doppia colorazione simboleggia l'armonia tra due energie complementari."
        ),
        "diaspore-zultanite" to GemTranslation(
            nom = "Zultanite",
            descriptionCourte = "Un cambiamento di colore dal verde kaki al rosa champagne, giacimento unico in Turchia.",
            descriptionLongue = "Commercializzata con il nome di «zultanite», questa varietà di diasporo cambia colore dal verde kaki olivastro sotto luce diurna al rosa champagne tendente al violaceo sotto luce incandescente, proveniente da un unico giacimento sulle montagne turche.",
            particularites = "Giacimento quasi unico al mondo; il cambiamento di colore è più sottile rispetto a quello dell'alessandrite.",
            lithotherapie = "La zultanite, che cambia colore a seconda della luce, è associata all'adattabilità e alla capacità di trasformazione personale."
        ),
        "ametrine" to GemTranslation(
            nom = "Ametrino",
            descriptionCourte = "Un quarzo bicolore in cui il viola dell'ametista e il giallo del citrino condividono uno stesso cristallo.",
            descriptionLongue = "L'ametrino deve la sua bicolorazione a un gradiente naturale di temperatura all'interno del cristallo di quarzo durante la sua crescita: le zone più calde hanno assunto la tonalità gialla del citrino, mentre quelle più fredde hanno conservato il viola dell'ametista. La miniera boliviana di Anahí, a lungo unica fonte commerciale al mondo, è legata a una leggenda del XVII secolo che ne attribuisce la scoperta a un conquistador spagnolo sposato con una principessa locale proprietaria del giacimento.",
            particularites = "Il taglio è pensato per mettere in risalto il netto contrasto tra le due zone di colore, spesso disposte in diagonale.",
            lithotherapie = "L'ametrino è ritenuto unire le virtù calmanti dell'ametista alle virtù stimolanti del citrino, un equilibrio tra calma interiore ed energia creativa."
        ),
        "grenat-couleur-changeante" to GemTranslation(
            nom = "Granato a cambiamento di colore",
            descriptionCourte = "Verde bluastro di giorno, rosso-violaceo di sera, un rivale poco conosciuto dell'alessandrite.",
            descriptionLongue = "Alcuni granati piropo-spessartina dell'Africa orientale presentano uno spettacolare cambiamento di colore, dal verde bluastro o grigio-verde sotto luce diurna al rosso-violaceo sotto luce incandescente, un fenomeno raro tra i granati.",
            particularites = "Il vanadio, piuttosto che il cromo, è responsabile del cambiamento di colore in questo granato.",
            lithotherapie = "Questo granato a cambiamento di colore simboleggia l'adattabilità e la capacità di rinnovarsi di fronte alle circostanze mutevoli."
        ),
        "pietersite" to GemTranslation(
            nom = "Pietersite",
            descriptionCourte = "Un vortice cangiante blu-dorato, soprannominato «occhio della tempesta».",
            descriptionLongue = "La pietersite è un quarzo con inclusioni fibrose di crocidolite spezzate e ricementate, che produce un effetto cangiante caotico blu, dorato e bruno che evoca una tempesta pietrificata — da cui il soprannome di «occhio della tempesta». Scoperta in Namibia nel 1962.",
            particularites = "Il motivo cangiante caotico, a differenza del regolare occhio di tigre, deriva da una frattura naturale delle fibre interne.",
            lithotherapie = "Soprannominata «pietra della tempesta», la pietersite è ritenuta sostenere il coraggio di fronte a cambiamenti rapidi e imprevisti."
        ),
        "agate" to GemTranslation(
            nom = "Agata",
            descriptionCourte = "La bandatura concentrica colorata più emblematica del quarzo.",
            descriptionLongue = "L'agata è una calcedonia che presenta bande concentriche o parallele dai colori variegati, formatesi per depositi successivi di silice in cavità vulcaniche. Le sue innumerevoli varietà (muschiata, dendritica, paesaggio, occhio...) ne fanno una delle pietre ornamentali più collezionate al mondo.",
            particularites = "La bandatura è spesso esaltata mediante tintura, una pratica antica e ampiamente accettata dal mercato.",
            lithotherapie = "L'agata è tradizionalmente associata all'equilibrio emotivo, alla stabilità e a una dolce protezione quotidiana."
        ),
        "jaspe" to GemTranslation(
            nom = "Diaspro",
            descriptionCourte = "Un quarzo opaco dai motivi infiniti, dal rosso sangue al verde paesaggio.",
            descriptionLongue = "Il diaspro è un aggregato microcristallino di quarzo reso opaco da numerose impurità minerali, che offre una tavolozza di colori e motivi quasi infinita. Il «diaspro paesaggio» imita intere scene naturali nella pietra levigata.",
            particularites = "Opacità totale a differenza dell'agata, dovuta alla densità delle impurità minerali incluse.",
            lithotherapie = "Il diaspro è ritenuto favorire il radicamento e la resistenza, un sostegno per tenere duro nei periodi impegnativi."
        ),
        "calcedoine" to GemTranslation(
            nom = "Calcedonio",
            descriptionCourte = "La forma microcristallina del quarzo, alla base di agata, corniola e onice.",
            descriptionLongue = "Il calcedonio è la forma criptocristallina (microcristalli invisibili a occhio nudo) del quarzo, da cui derivano agata, corniola, crisoprasio e onice. La varietà blu-grigia translucida, detta «calcedonio blu», è la più ricercata in gioielleria.",
            particularites = "Termine generico che designa il quarzo microcristallino; agata, corniola e onice ne sono varietà denominate.",
            lithotherapie = "Il calcedonio è associato all'armonia interiore e a una comunicazione serena con il proprio ambiente."
        ),
        "quartz-a-inclusions" to GemTranslation(
            nom = "Quarzo a inclusioni (giardino)",
            descriptionCourte = "Un paesaggio minerale in miniatura racchiuso in un cristallo limpido.",
            descriptionLongue = "Numerose varietà di quarzo limpido racchiudono inclusioni di altri minerali — clorite, actinolite, ematite, rutilo, litiofilite, fuchsite o pirite a seconda dei giacimenti — creando paesaggi interni unici soprannominati «quarzo giardino» (lodolite) o quarzo fantasma.",
            particularites = "Ogni pietra è unica a seconda della natura del minerale incluso; non esistono due quarzi a inclusioni identici.",
            lithotherapie = "Il quarzo a inclusioni (detto «giardino») invita all'introspezione, ogni inclusione simboleggia una sfaccettatura del mondo interiore."
        ),
        "quartz-rutile" to GemTranslation(
            nom = "Quarzo rutilato",
            descriptionCourte = "«Capelli di Venere» dorati racchiusi in un cristallo di rocca limpido.",
            descriptionLongue = "Il quarzo rutilato imprigiona sottili aghi dorati di rutilo, poeticamente soprannominati «capelli di Venere» o «frecce d'amore», creando un effetto decorativo sorprendente molto ricercato nella gioielleria contemporanea.",
            particularites = "Le inclusioni di rutilo possono anche produrre un effetto occhio di gatto quando il cristallo è tagliato a cabochon.",
            lithotherapie = "Il quarzo rutilato unisce le virtù amplificatrici del cristallo di rocca a un potere protettivo rafforzato."
        ),
        "quartz-super-sept" to GemTranslation(
            nom = "Quarzo super sette",
            descriptionCourte = "Fino a sette minerali riuniti in un unico cristallo di ametista brasiliana.",
            descriptionLongue = "Il «Super Seven» (o melody stone) è un quarzo ametistato del Brasile che racchiude fino a sette minerali distinti come inclusioni — cacoxenite, goethite, lepidocrocite, rutilo, ematite tra gli altri — creando motivi dorati e violacei unici per ogni pietra.",
            particularites = "Giacimento unico al mondo; il nome commerciale fa riferimento ai sette minerali che possono essere presenti.",
            lithotherapie = "Rara associazione di sette minerali, il quarzo super sette è ritenuto favorire una meditazione profonda e una forma di sintesi spirituale."
        ),
        "smithsonite" to GemTranslation(
            nom = "Smithsonite",
            descriptionCourte = "Mammelloni botrioidali «caramella» in un'ampia tavolozza pastello.",
            descriptionLongue = "La smithsonite forma masse botrioidali dalle tonalità pastello molto varie — rosa, blu, verde, giallo o malva a seconda delle tracce metalliche presenti — la cui superficie setosa e arrotondata evoca delle caramelle, molto apprezzata a cabochon.",
            particularites = "Il colore varia in base al metallo in traccia: rame (blu-verde), cobalto (rosa), cadmio (giallo).",
            lithotherapie = "La smithsonite è associata alla dolcezza e alla pacificazione emotiva, un sostegno per calmare l'irritabilità."
        ),
        "moldavite" to GemTranslation(
            nom = "Moldavite",
            descriptionCourte = "Un vetro verde oliva nato dall'impatto di un meteorite 15 milioni di anni fa.",
            descriptionLongue = "La moldavite è un vetro naturale formatosi dalla fusione istantanea di rocce terrestri durante l'impatto di un meteorite in Baviera circa 15 milioni di anni fa, che proiettò goccioline di vetro fuso fino in Boemia, dove oggi la si trova.",
            particularites = "Giacimento geograficamente unico al mondo, legato al cratere da impatto di Ries in Baviera (Germania).",
            lithotherapie = "Di origine meteoritica, la moldavite è ritenuta provocare una trasformazione interiore intensa e un risveglio spirituale accelerato."
        ),
        "verre-libyque" to GemTranslation(
            nom = "Vetro libico",
            descriptionCourte = "Un vetro giallo translucido del deserto, presente nel gioiello pettorale di Tutankhamon.",
            descriptionLongue = "Il vetro libico è un vetro naturale dal giallo pallido al giallo-verde, formatosi 29 milioni di anni fa nel deserto libico a seguito di un impatto meteoritico o di un'esplosione aerea. Uno scarabeo intagliato in questo vetro orna il pettorale funerario di Tutankhamon.",
            particularites = "Utilizzato dagli artigiani egizi antichi più di 3.000 anni fa, ben prima della sua descrizione scientifica moderna.",
            lithotherapie = "Formatosi a seguito di un impatto meteoritico milioni di anni fa, il vetro libico è associato alla lucidità mentale e a una protezione solare simbolica."
        ),
        "alexandrite" to GemTranslation(
            nom = "Alessandrite",
            descriptionCourte = "Verde di giorno, rosso sotto luce incandescente.",
            descriptionLongue = "Scoperta negli Urali nel XIX secolo e battezzata in onore del futuro zar Alessandro II, l'alessandrite cambia colore in modo spettacolare: verde smeraldo alla luce del giorno, rosso porpora sotto illuminazione incandescente. Le pietre che presentano un cambiamento marcato sono estremamente rare e ricercate.",
            particularites = "La percentuale di cambiamento di colore è il principale criterio di valutazione.",
            lithotherapie = "L'alessandrite, che cambia colore a seconda della luce, è ritenuta favorire l'adattabilità e l'equilibrio tra ragione e intuizione."
        ),
        "tourmaline-pasteque" to GemTranslation(
            nom = "Tormalina anguria",
            descriptionCourte = "Cuore rosa cinto di verde, come una fetta di frutto.",
            descriptionLongue = "Risultato di una crescita cristallina avvenuta in più fasi chimiche, la tormalina anguria presenta un cuore rosa circondato da uno strato verde, tagliata in fette sottili per rivelare questo sorprendente motivo naturale.",
            particularites = "Tagliata il più delle volte in fette trasversali per rivelare l'effetto «anguria».",
            lithotherapie = "La tormalina anguria unisce le virtù rasserenanti del rosa all'energia protettiva del verde, simboleggiando l'equilibrio tra cuore e azione."
        ),
        "labradorite" to GemTranslation(
            nom = "Labradorite",
            descriptionCourte = "Riflessi metallici mobili (labradorescenza).",
            descriptionLongue = "La labradorite presenta un fenomeno ottico chiamato labradorescenza: bagliori blu-verdi, talvolta dorati o violacei, appaiono e scompaiono a seconda dell'angolo di osservazione, dovuti a lamelle interne che diffrangono la luce.",
            particularites = "L'orientamento del taglio è determinante per rivelare la labradorescenza.",
            lithotherapie = "La labradorite è ritenuta offrire una forte protezione energetica stimolando al contempo l'intuizione e la magia del quotidiano."
        ),
        "pierre-de-lune" to GemTranslation(
            nom = "Pietra di luna",
            descriptionCourte = "Bagliore bluastro fluttuante (adularescenza).",
            descriptionLongue = "La pietra di luna deve il suo nome al bagliore bluastro fluttuante, l'adularescenza, causata dall'intercrescita di due feldspati su scala microscopica che diffrangono la luce. Le migliori qualità blu vivo provengono dallo Sri Lanka.",
            particularites = "Adularescenza ottimale quando la pietra è tagliata a cabochon perpendicolarmente alle lamelle interne.",
            lithotherapie = "La pietra di luna è tradizionalmente associata all'intuizione, alla sensibilità e ai nuovi inizi, in relazione ai cicli lunari."
        ),
        "pierre-de-soleil" to GemTranslation(
            nom = "Pietra di sole",
            descriptionCourte = "Scintillio ramato dovuto a inclusioni di rame.",
            descriptionLongue = "Al contrario della pietra di luna, la pietra di sole deve il suo caldo scintillio (avventurescenza) a sottili pagliuzze di rame o ematite incluse nel cristallo, che producono riflessi dall'arancio al rosso ramato a seconda dell'illuminazione.",
            particularites = "Avventurescenza dovuta a pagliuzze di rame nativo, a differenza del quarzo avventurina colorato dalla fuchsite.",
            lithotherapie = "La pietra di sole è ritenuta portare gioia di vivere, vitalità e fiducia in se stessi, a immagine del suo calore luminoso."
        ),
        "fluorine" to GemTranslation(
            nom = "Fluorite",
            descriptionCourte = "La tavolozza di colori più estesa del regno minerale.",
            descriptionLongue = "La fluorite può presentarsi in quasi tutti i colori, talvolta più di uno in uno stesso cristallo zonato. La sua tenerezza e la sfaldatura perfetta in quattro direzioni ne limitano l'uso in gioielleria, ma ne fanno una pietra da collezione estremamente apprezzata.",
            particularites = "Sfaldatura perfetta in quattro direzioni; fluorescenza caratteristica sotto UV all'origine del termine «fluorescenza».",
            lithotherapie = "La fluorite è molto utilizzata per favorire la concentrazione e la lucidità mentale, in particolare durante i periodi di studio o di lavoro intenso."
        ),
        "ammolite" to GemTranslation(
            nom = "Ammolite",
            descriptionCourte = "L'iridescenza racchiusa di conchiglie di ammoniti fossili.",
            descriptionLongue = "L'ammolite proviene dalla madreperla fossilizzata di conchiglie di ammoniti vecchie di 70 milioni di anni, rinvenute quasi esclusivamente lungo le Montagne Rocciose canadesi. Mostra un'iridescenza multicolore paragonabile a quella dell'opale, unica tra le gemme organiche.",
            particularites = "Gemma organica fossile; quasi monopolio geografico nel sud dell'Alberta.",
            lithotherapie = "L'ammolite, gemma organica fossile, è associata alla fortuna, alla vitalità e alla trasformazione positiva."
        ),
        "corail" to GemTranslation(
            nom = "Corallo rosso",
            descriptionCourte = "Lo scheletro calcareo di un animale marino, rosso sangue prezioso fin dall'antichità.",
            descriptionLongue = "Il corallo rosso prezioso è lo scheletro calcareo ramificato di un piccolo animale marino coloniale (Corallium rubrum), raccolto nel Mediterraneo fin dall'antichità. Il suo sfruttamento eccessivo ne ha fatto oggi una gemma organica rigorosamente regolamentata.",
            particularites = "Raccolta rigorosamente regolamentata (CITES per alcune specie) a causa dello sfruttamento eccessivo storico delle barriere coralline.",
            lithotherapie = "Il corallo rosso è tradizionalmente indossato come protezione, in particolare per i bambini, ed è associato alla vitalità e all'energia familiare."
        ),
        "perle-conque" to GemTranslation(
            nom = "Perla di conchiglia regina (Lambi)",
            descriptionCourte = "Una perla rosa fiammata senza madreperla, proveniente dal lambi dei Caraibi.",
            descriptionLongue = "La perla di conchiglia regina, o perla Lambi, si forma nella conchiglia regina (Strombus gigas) dei Caraibi. A differenza delle classiche perle madreperlacee, non è madreperlacea e deve la sua lucentezza setosa e il caratteristico motivo a «fiamma» alla struttura fibrosa dell'aragonite.",
            particularites = "Struttura a «fiamma» visibile in superficie, esclusiva delle perle non madreperlacee come la perla di conchiglia regina o la perla di melo.",
            lithotherapie = "La perla di conchiglia regina è associata alla femminilità, all'intuizione e alla dolcezza emotiva."
        ),
        "ambre" to GemTranslation(
            nom = "Ambra",
            descriptionCourte = "Resina d'albero fossilizzata da milioni di anni.",
            descriptionLongue = "L'ambra è resina di conifere o di alberi da fiore fossilizzata nel corso di milioni di anni. La sua caratteristica leggerezza e le sue inclusioni talvolta spettacolari (insetti, vegetali) ne hanno fatto un materiale prezioso fin dalla preistoria, in particolare lungo la «via dell'ambra» baltica.",
            particularites = "Galleggia nell'acqua salata; può contenere inclusioni fossili (insetti, vegetali) molto ricercate.",
            lithotherapie = "L'ambra è rinomata fin dall'antichità per le sue virtù rasserenanti e protettive, che apportano calore e conforto emotivo."
        ),
        "perle" to GemTranslation(
            nom = "Perla coltivata",
            descriptionCourte = "L'unica gemma prodotta da un essere vivente.",
            descriptionLongue = "Formata da un mollusco in reazione a un corpo estraneo, la perla è costituita da strati concentrici di madreperla. La quasi totalità delle perle commercializzate oggi sono perle coltivate (Akoya, Tahiti, mari del Sud), con l'intervento umano limitato all'impianto del nucleo iniziale.",
            particularites = "Prezzo valutato al pezzo o al filo secondo dimensione, forma, lustro e provenienza, non al carato.",
            lithotherapie = "La perla coltivata è associata alla purezza, alla saggezza e all'armonia nelle relazioni affettive."
        ),
        "aventurine" to GemTranslation(
            nom = "Avventurina verde",
            descriptionCourte = "Un quarzo verde scintillante, punteggiato da pagliuzze di fuchsite.",
            descriptionLongue = "L'avventurina deve il proprio nome e il caratteristico scintillio (avventurescenza) a fini inclusioni di mica cromifera (fuchsite) o di ematite disseminate in una massa di quarzo microcristallino. La varietà verde, la più diffusa, viene estratta in grandi quantità in India da secoli.",
            particularites = "L'avventurescenza, questo scintillio metallico, deriva dalla riflessione della luce sulle pagliuzze di mica incluse; il termine è stato in seguito ripreso per designare il vetro artificiale che imita questo effetto.",
            lithotherapie = "L'avventurina verde è ritenuta un portafortuna, associata alla fortuna, all'abbondanza e alla distensione emotiva."
        ),
        "epidote" to GemTranslation(
            nom = "Epidoto",
            descriptionCourte = "Un verde pistacchio caratteristico, raramente sfaccettato a causa del suo marcato pleocroismo.",
            descriptionLongue = "L'epidoto dà il nome a un intero gruppo minerale e si presenta in cristalli allungati dal verde pistacchio al verde oliva, colore dovuto al ferro. Il suo forte pleocroismo, che fa apparire tonalità diverse a seconda dell'angolo di osservazione, complica la lavorazione di pietre dal colore omogeneo.",
            particularites = "Il forte pleocroismo (verde, giallo-bruno, incolore rosato a seconda dell'angolo) va tenuto in considerazione durante la lavorazione per rivelare la faccia colorata più bella.",
            lithotherapie = "L'epidoto è ritenuto favorire la trasformazione personale e aiutare a liberarsi da schemi emotivi ripetitivi."
        ),
        "gaspeite" to GemTranslation(
            nom = "Gaspeite",
            descriptionCourte = "Un carbonato di nichel verde mela opaco, raro e ricercato per i cabochon.",
            descriptionLongue = "La gaspeite è un carbonato di nichel di un verde mela a verde vivo opaco, scoperto nella penisola della Gaspesia, in Québec, da cui prende il nome. I giacimenti australiani sfruttabili in qualità gemma ne costituiscono oggi la principale fonte commerciale.",
            particularites = "Spesso confusa a distanza con la turchese o la variscite per via della sua tonalità verde opaca, ma se ne distingue per il colore più decisamente verde mela.",
            lithotherapie = "La gaspeite è associata all'abbondanza e a un radicamento dolce, favorendo la stabilità nei periodi di cambiamento."
        ),
        "hiddenite" to GemTranslation(
            nom = "Hiddenite",
            descriptionCourte = "La varietà verde dello spodumene, colorata dal cromo, cugina della kunzite.",
            descriptionLongue = "L'hiddenite è la varietà verde dello spodumene, il cui colore deriva da tracce di cromo o di vanadio — a differenza della kunzite rosa, che deve il suo al manganese. Scoperta in Carolina del Nord alla fine del XIX secolo, il materiale migliore resta quello americano, sebbene anche il Brasile e l'Afghanistan ne producano.",
            particularites = "Come tutte le varietà di spodumene, possiede una sfaldatura perfetta in due direzioni e deve essere lavorata con cautela.",
            lithotherapie = "L'hiddenite è ritenuta aprire il cuore alla compassione, apportando al contempo chiarezza e discernimento nelle decisioni importanti."
        ),
        "angelite" to GemTranslation(
            nom = "Angelite",
            descriptionCourte = "La varietà azzurro cielo dell'anidrite, molto apprezzata in litoterapia.",
            descriptionLongue = "L'angelite è il nome commerciale dato all'anidrite di un azzurro pallido e latteo, levigata in cabochon, perle o oggetti decorativi. Il suo colore deriva da tracce di impurità nel solfato di calcio anidro, che si forma quando il gesso viene compresso e perde la propria acqua nel corso di lunghi periodi geologici.",
            particularites = "Si graffia facilmente e teme l'umidità prolungata, che può lentamente idratarla trasformandola in gesso; va protetta dall'acqua e dagli urti.",
            lithotherapie = "L'angelite è associata alla comunicazione, alla serenità e a una forma di connessione spirituale distesa, da cui il suo nome evocativo."
        ),
        "oeil-de-faucon" to GemTranslation(
            nom = "Occhio di falco",
            descriptionCourte = "La variante blu-grigia cangiante dell'occhio di tigre, non ossidata.",
            descriptionLongue = "L'occhio di falco condivide l'origine dell'occhio di tigre: una pseudomorfosi di quarzo dopo la crocidolite (amianto blu), le cui fibre parallele producono un riflesso setoso. A differenza dell'occhio di tigre dorato, conserva la tonalità originaria dal blu-grigio al blu-verde, per mancata ossidazione del ferro.",
            particularites = "Lo stesso blocco di materiale grezzo può presentare localmente zone blu-grigie (occhio di falco) e dorate (occhio di tigre) a seconda del grado di ossidazione del ferro.",
            lithotherapie = "L'occhio di falco è tradizionalmente associato alla chiaroveggenza, alla visione interiore e alla capacità di prendere le distanze di fronte a situazioni complesse."
        ),
        "howlite" to GemTranslation(
            nom = "Howlite",
            descriptionCourte = "Una pietra bianca venata di grigio, spesso tinta per imitare la turchese.",
            descriptionLongue = "La howlite si presenta naturalmente in noduli bianchi dalla struttura porosa, attraversati da venature grigie a nere che evocano una marmorizzazione. La sua porosità la rende facile da tingere, il che ne fa il materiale più comunemente utilizzato per imitare la turchese a basso costo — una pratica da verificare sempre prima dell'acquisto.",
            particularites = "La sua forte porosità la rende particolarmente ricettiva alle tinture, all'origine di numerose imitazioni di turchese o lapislazzuli sul mercato.",
            lithotherapie = "La howlite è ritenuta calmare la mente agitata e favorire un sonno più sereno."
        ),
        "rhodizite" to GemTranslation(
            nom = "Rodizite",
            descriptionCourte = "Un borato ultra-raro, uno dei minerali più duri dopo il corindone.",
            descriptionLongue = "La rodizite è un borato complesso di cesio, berillio e alluminio, che cristallizza in minuscoli cristalli incolori a giallo pallido quasi esclusivamente in Madagascar. La sua eccezionale durezza, vicina a quella del corindone, e la sua estrema rarità ne fanno una pietra quasi esclusivamente destinata ai collezionisti esperti.",
            particularites = "I cristalli sfaccettabili che superano un carato sono eccezionalmente rari; la maggior parte delle pietre tagliate pesa meno di 0,5 carati.",
            lithotherapie = "La rodizite è associata all'armonizzazione energetica e all'amplificazione delle intenzioni positive."
        ),
        "sanidine" to GemTranslation(
            nom = "Sanidino",
            descriptionCourte = "Un feldspato vulcanico incolore a giallo pallido, cristallizzato rapidamente in superficie.",
            descriptionLongue = "Il sanidino è la forma ad alta temperatura del feldspato potassico, che cristallizza rapidamente nelle rocce vulcaniche e nelle lave, il che lo distingue dall'ortoclasio formatosi più lentamente in profondità. I cristalli limpidi e sfaccettabili più ricercati provengono dalle proiezioni vulcaniche dell'Eifel, in Germania.",
            particularites = "Si distingue dall'ortoclasio per la sua formazione vulcanica rapida e la struttura atomica più disordinata; entrambi condividono la stessa formula chimica.",
            lithotherapie = "Il sanidino è associato alla chiarezza mentale e alla spontaneità, in eco alla sua rapida formazione nelle rocce vulcaniche."
        ),
        "tremolite" to GemTranslation(
            nom = "Tremolite",
            descriptionCourte = "Un anfibolo bianco a grigio, la cui varietà rosa è molto più ricercata.",
            descriptionLongue = "La tremolite è un anfibolo calcio-magnesiaco che costituisce il polo ricco di magnesio della serie tremolite-attinolite; in forma fibrosa compatta, costituisce uno dei componenti della nefrite. La sua varietà gemma, generalmente bianca, grigia o incolore, viene raramente sfaccettata, ad eccezione della rara varietà violacea detta esagonite.",
            particularites = "La rarissima varietà rosa-violacea, l'esagonite, deve il suo colore al manganese e viene talvolta confusa con la tanzanite prima dell'analisi.",
            lithotherapie = "La tremolite è ritenuta apportare dolcezza e flessibilità di fronte ai cambiamenti, in risonanza con la sua struttura fibrosa."
        ),
        "oeil-de-taureau" to GemTranslation(
            nom = "Occhio di toro",
            descriptionCourte = "L'occhio di tigre riscaldato, la cui ossidazione del ferro vira verso un rosso-bruno profondo.",
            descriptionLongue = "L'occhio di toro si ottiene mediante riscaldamento controllato dell'occhio di tigre dorato, un trattamento che accentua l'ossidazione del ferro e fa virare la tonalità dal giallo-bruno a un rosso-bruno profondo e intenso, conservando al contempo il caratteristico riflesso setoso della struttura fibrosa.",
            particularites = "Il trattamento termico che produce questa tonalità rosso-bruna è comune e ampiamente accettato nel commercio, a condizione che venga dichiarato.",
            lithotherapie = "L'occhio di toro è associato alla forza, al radicamento e alla determinazione, in continuità simbolica con l'occhio di tigre."
        ),
        "unakite" to GemTranslation(
            nom = "Unakite",
            descriptionCourte = "Una roccia screziata di verde e rosa, mescolanza di granito alterato.",
            descriptionLongue = "L'unakite è una roccia granitica alterata, composta da una caratteristica mescolanza di feldspato rosa, epidoto verde e quarzo, che le conferisce un motivo maculato immediatamente riconoscibile. Prende il nome dai monti Unaka in Carolina del Nord, dove fu descritta, ed è lavorata soprattutto in cabochon e perle.",
            particularites = "Trattandosi di una roccia composita e non di un minerale unico, la sua durezza e il suo indice di rifrazione variano leggermente a seconda della proporzione di ciascun componente.",
            lithotherapie = "L'unakite è tradizionalmente associata all'equilibrio affettivo e alla guarigione progressiva dopo una prova emotiva."
        ),
        "oeil-de-sainte-lucie" to GemTranslation(
            nom = "Occhio di Santa Lucia",
            descriptionCourte = "L'opercolo spiraliforme di una lumaca marina, indossato come amuleto sin dall'Antichità.",
            descriptionLongue = "L'occhio di Santa Lucia è l'opercolo calcareo, la piccola «porta» che chiude l'apertura del guscio di alcuni gasteropodi marini del genere Turbo. Il suo motivo a spirale marrone e crema, che evoca un occhio, ne ha fatto un amuleto protettivo tradizionale in numerose culture mediterranee.",
            particularites = "Non si tratta di un guscio ma dell'opercolo, il pezzo calcareo che richiude l'apertura del mollusco vivente; si stacca naturalmente dopo la morte dell'animale.",
            lithotherapie = "Indossato come pendente sin dall'Antichità, questo amuleto è ritenuto proteggere dal malocchio e portare fortuna a chi lo indossa."
        ),
        "jais" to GemTranslation(
            nom = "Giaietto",
            descriptionCourte = "Un carbone fossile nero opaco, emblema del lutto vittoriano.",
            descriptionLongue = "Il giaietto è una varietà compatta di lignite, legno fossilizzato sotto alta pressione nel corso di milioni di anni, levigato fino a ottenere un nero profondo e vellutato. La sua leggerezza e la facilità di lavorazione ne hanno fatto il materiale emblematico dei gioielli da lutto dell'epoca vittoriana, in particolare nella zona di Whitby, in Inghilterra.",
            particularites = "Si riscalda rapidamente a contatto con la pelle e può sviluppare una carica elettrostatica per sfregamento, come l'ambra.",
            lithotherapie = "Il giaietto è tradizionalmente associato alla protezione dalle energie negative e all'accompagnamento nel lutto."
        ),
        "grenat-etoile" to GemTranslation(
            nom = "Granato stellato",
            descriptionCourte = "Un almandino a quattro o sei bracci luminosi, una rarità che si trova quasi esclusivamente nell'Idaho.",
            descriptionLongue = "Il granato stellato è un almandino le cui sottili inclusioni orientate (generalmente di rutilo) producono un asterismo a quattro o, più raramente, sei bracci sotto una luce puntiforme. È noto in qualità da gemma solo in due luoghi al mondo: l'Idaho, negli Stati Uniti, e alcuni giacimenti dell'India.",
            particularites = "L'Idaho è l'unico luogo al mondo in cui si trovano granati con asterismo a quattro bracci; le stelle a sei bracci, più rare, provengono dagli stessi giacimenti.",
            lithotherapie = "Il granato stellato è associato alla forza interiore e alla guida nei momenti di incertezza."
        ),
        "opale-peruvienne" to GemTranslation(
            nom = "Opale peruviana",
            descriptionCourte = "Un'opale opaca blu-verde o rosa, priva di gioco di colori, unica al Perù.",
            descriptionLongue = "L'opale peruviana è un'opale comune opaca, di un blu-verde che evoca l'acqua di mare o, più raramente, di un rosa tenue — due tonalità dovute a tracce di rame. Estratta unicamente sulle Ande peruviane, viene tagliata a cabochon per la gioielleria.",
            particularites = "Il suo colore deriva da tracce di rame, un fenomeno di colorazione raro nelle opali, di norma incolori in profondità.",
            lithotherapie = "L'opale peruviana è associata alla distensione emotiva e alla comunicazione, in risonanza con la sua tonalità blu-verde."
        ),
        "opale-commune" to GemTranslation(
            nom = "Opale comune",
            descriptionCourte = "La varietà più diffusa di opale, lattiginosa e priva di gioco di colori.",
            descriptionLongue = "L'opale comune, o opale lattea, costituisce la maggior parte della produzione mondiale di opale ma non presenta il gioco di colori che fa il pregio dell'opale preziosa. Bianca, translucida o talvolta colorata, viene tagliata a cabochon a prezzo accessibile.",
            particularites = "L'assenza di gioco di colori distingue l'opale comune dall'opale preziosa; le due condividono tuttavia la stessa composizione.",
            lithotherapie = "L'opale comune è ritenuta capace di apportare dolcezza e serenità nella vita quotidiana."
        ),
        "opale-noire" to GemTranslation(
            nom = "Opale nera",
            descriptionCourte = "Il gioco di colori più spettacolare, su un fondo scuro che lo esalta.",
            descriptionLongue = "L'opale nera deve il suo nome al fondo scuro, dal grigio al nero, sul quale il gioco di colori risalta con un'intensità impareggiabile. Estratta quasi esclusivamente a Lightning Ridge, nel Nuovo Galles del Sud, è considerata la più preziosa tra le opali.",
            particularites = "Il fondo scuro deriva da tracce di carbonio e ossidi di ferro tra le sferule di silice, un fenomeno proprio del giacimento di Lightning Ridge.",
            lithotherapie = "L'opale nera è associata alla trasformazione interiore e alla protezione nei periodi di cambiamento profondo."
        ),
        "opale-boulder" to GemTranslation(
            nom = "Opale Boulder",
            descriptionCourte = "Un sottile velo di opale sulla sua ganga di arenaria ferruginosa bruna, lasciata intatta durante la lavorazione.",
            descriptionLongue = "L'opale Boulder si forma in sottili vene all'interno di una roccia ferruginosa bruna (ironstone) del Queensland. Anziché separare l'opale dalla sua ganga, troppo sottile e fragile, i lapidari tagliano la pietra conservando il fondo bruno naturale, che valorizza il gioco di colori.",
            particularites = "A differenza delle altre opali, include deliberatamente la roccia ospite, il che la rende più resistente agli urti rispetto a un'opale pura.",
            lithotherapie = "L'opale Boulder è associata al radicamento e alla solidità, in risonanza con la roccia che la sostiene."
        ),
        "opale-ethiopie" to GemTranslation(
            nom = "Opale d'Etiopia",
            descriptionCourte = "Un'opale dal gioco di colori vivace su fondo miele, ma idrofana e quindi fragile a contatto con l'acqua.",
            descriptionLongue = "Scoperta negli anni 2010 nella regione di Wollo, l'opale d'Etiopia ha rivoluzionato il mercato grazie al suo gioco di colori particolarmente vivace su un fondo translucido dal miele all'incolore. La sua natura idrofana — assorbe l'acqua come una spugna — la rende tuttavia instabile se immersa o troppo esposta all'umidità.",
            particularites = "Natura idrofana: può assorbire fino al 20% del proprio volume in acqua, screpolarsi durante l'asciugatura e vedere la propria trasparenza cambiare temporaneamente a contatto con l'umidità.",
            lithotherapie = "L'opale d'Etiopia è ritenuta capace di amplificare le emozioni e la creatività, come le altre opali preziose."
        ),
    )
}
